 206→func StatePath(ctx context.Context) (string, error) {
 207→	path, err := paths.AbsPath(ctx, filepath.Join(paths.EntireDir, fileName))
 208→	if err != nil {
 209→		return "", fmt.Errorf("resolve memory-loop path: %w", err)
 210→	}
 211→	return path, nil
 212→}
