 214→func LoadState(ctx context.Context) (*State, error) {
 215→	path, err := StatePath(ctx)
 216→	if err != nil {
 217→		return nil, err
 218→	}
 219→
 220→	data, err := os.ReadFile(path) //nolint:gosec // repo-local metadata path
 221→	if err != nil {
 222→		if os.IsNotExist(err) {
 223→			return &State{}, nil
 224→		}
 225→		return nil, fmt.Errorf("read memory-loop state: %w", err)
 226→	}
 227→
 228→	var disk diskState
 229→	if err := json.Unmarshal(data, &disk); err != nil {
 230→		return nil, fmt.Errorf("parse memory-loop state: %w", err)
 231→	}
 232→
 233→	state := &State{
 234→		Store:         disk.Store,
 235→		Snapshot:      disk.Snapshot,
 236→		InjectionLogs: disk.InjectionLogs,
 237→	}
 238→	normalizeStateWithSource(state, disk.Store == nil && disk.Snapshot != nil)
 239→	return state, nil
 240→}
