 242→func SaveState(ctx context.Context, state *State) error {
 243→	if state == nil {
 244→		state = &State{}
 245→	}
 246→	normalizeState(state)
 247→
 248→	path, err := StatePath(ctx)
 249→	if err != nil {
 250→		return err
 251→	}
 252→	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
 253→		return fmt.Errorf("create memory-loop directory: %w", err)
 254→	}
 255→
 256→	data, err := jsonutil.MarshalIndentWithNewline(diskState{
 257→		Store:         state.Store,
 258→		InjectionLogs: state.InjectionLogs,
 259→	}, "", "  ")
 260→	if err != nil {
 261→		return fmt.Errorf("marshal memory-loop state: %w", err)
 262→	}
 263→	if err := os.WriteFile(path, data, 0o644); err != nil { //nolint:gosec // repo-local metadata path
 264→		return fmt.Errorf("write memory-loop state: %w", err)
 265→	}
 266→	return nil
 267→}
