 269→func AppendInjectionLog(ctx context.Context, log InjectionLog) error {
 270→	state, err := LoadState(ctx)
 271→	if err != nil {
 272→		return err
 273→	}
 274→	state.InjectionLogs = append(state.InjectionLogs, log)
 275→	if len(state.InjectionLogs) > maxInjectionLogs {
 276→		state.InjectionLogs = state.InjectionLogs[len(state.InjectionLogs)-maxInjectionLogs:]
 277→	}
 278→	return SaveState(ctx, state)
 279→}
