 281→func SelectRelevant(snapshot Snapshot, prompt string, now time.Time) []Match {
 282→	maxInjected := snapshot.MaxInjected
 283→	if maxInjected <= 0 {
 284→		maxInjected = DefaultMaxInjected
 285→	}
 286→
 287→	promptTokens := tokenize(prompt)
 288→	if len(promptTokens) == 0 {
 289→		return nil
 290→	}
 291→
 292→	matches := make([]Match, 0, len(snapshot.Records))
 293→	for _, record := range snapshot.Records {
 294→		if record.Status != "" && record.Status != StatusActive {
 295→			continue
 296→		}
 297→		score, reason := scoreRecord(record, promptTokens, now)
 298→		if score <= 0 {
 299→			continue
 300→		}
 301→		matches = append(matches, Match{
 302→			Record: record,
 303→			Score:  score,
 304→			Reason: reason,
 305→		})
 306→	}
 307→
 308→	sort.SliceStable(matches, func(i, j int) bool {
 309→		if matches[i].Score != matches[j].Score {
 310→			return matches[i].Score > matches[j].Score
 311→		}
 312→		if matches[i].Record.Strength != matches[j].Record.Strength {
 313→			return matches[i].Record.Strength > matches[j].Record.Strength
 314→		}
 315→		return matches[i].Record.Title < matches[j].Record.Title
 316→	})
 317→
 318→	if len(matches) > maxInjected {
 319→		matches = matches[:maxInjected]
 320→	}
 321→	return matches
 322→}
