 324→func ReconcileGeneratedRecords(existing, generated []MemoryRecord, scopeKind ScopeKind, scopeValue string, policy ActivationPolicy, now time.Time) ReconcileResult {
 325→	records := append([]MemoryRecord(nil), existing...)
 326→	byScopeKey := make(map[string]int, len(records))
 327→	for i := range records {
 328→		fingerprint := records[i].Fingerprint
 329→		if fingerprint == "" {
 330→			fingerprint = fingerprintForRecord(records[i].Kind, records[i].Title, records[i].Body)
 331→			records[i].Fingerprint = fingerprint
 332→		}
 333→		if records[i].ScopeKind == "" {
 334→			records[i].ScopeKind = scopeKind
 335→		}
 336→		byScopeKey[recordScopeKey(records[i].Fingerprint, records[i].ScopeKind, records[i].ScopeValue)] = i
 337→	}
 338→
 339→	result := ReconcileResult{
 340→		Records: records,
 341→		History: RefreshHistory{
 342→			At:           now,
 343→			Scope:        string(scopeKind),
 344→			ScopeValue:   scopeValue,
 345→			SourceWindow: DefaultRefreshWindow,
 346→		},
 347→	}
 348→
 349→	for _, generatedRecord := range generated {
 350→		result.History.GeneratedCount++
 351→
 352→		record := generatedRecord
 353→		if record.Kind == "" {
 354→			record.Kind = KindRepoRule
 355→		}
 356→		if record.Origin == "" {
 357→			record.Origin = OriginGenerated
 358→		}
 359→		if record.Fingerprint == "" {
 360→			record.Fingerprint = fingerprintForRecord(record.Kind, record.Title, record.Body)
 361→		}
 362→		if record.ScopeKind == "" {
 363→			record.ScopeKind = scopeKind
 364→		}
 365→		if record.ScopeValue == "" {
 366→			record.ScopeValue = scopeValue
 367→		}
 368→		if record.CreatedAt.IsZero() {
 369→			record.CreatedAt = now
 370→		}
 371→		record.UpdatedAt = now
 372→
 373→		if idx, exists := findReconcileIndex(result.Records, byScopeKey, record); exists {
 374→			reconciled := result.Records[idx]
 375→			reconciled.Kind = record.Kind
 376→			reconciled.Title = record.Title
 377→			reconciled.Body = record.Body
 378→			reconciled.Why = record.Why
 379→			reconciled.Evidence = record.Evidence
 380→			reconciled.SourceSessionIDs = record.SourceSessionIDs
 381→			reconciled.Confidence = record.Confidence
 382→			reconciled.Strength = record.Strength
 383→			reconciled.Fingerprint = record.Fingerprint
 384→			reconciled.ScopeKind = record.ScopeKind
 385→			reconciled.ScopeValue = record.ScopeValue
 386→			reconciled.Origin = record.Origin
 387→			reconciled.UpdatedAt = now
 388→			reconciled.Status = reconciledStatus(reconciled.Status, record.ScopeKind, policy)
 389→			switch reconciled.Status {
 390→			case StatusActive:
 391→				result.History.ActivatedCount++
 392→			case StatusCandidate:
 393→				result.History.CandidateCount++
 394→			case StatusSuppressed, StatusArchived:
 395→			}
 396→			result.Records[idx] = reconciled
 397→			continue
 398→		}
 399→
 400→		record.Status = reconciledStatus(record.Status, record.ScopeKind, policy)
 401→		switch record.Status {
 402→		case StatusActive:
 403→			result.History.ActivatedCount++
 404→		case StatusCandidate:
 405→			result.History.CandidateCount++
 406→		case StatusSuppressed, StatusArchived:
 407→		}
 408→
 409→		result.Records = append(result.Records, record)
 410→		byScopeKey[recordScopeKey(record.Fingerprint, record.ScopeKind, record.ScopeValue)] = len(result.Records) - 1
 411→	}
 412→
 413→	return result
 414→}
