 436→func recordScopeKey(fingerprint string, scopeKind ScopeKind, scopeValue string) string {
 437→	return strings.Join([]string{fingerprint, string(scopeKind), scopeValue}, "|")
 438→}
 439→
 440→func findReconcileIndex(records []MemoryRecord, byScopeKey map[string]int, record MemoryRecord) (int, bool) {
 441→	if idx, exists := byScopeKey[recordScopeKey(record.Fingerprint, record.ScopeKind, record.ScopeValue)]; exists {
 442→		return idx, true
 443→	}
 444→	if record.ScopeKind == ScopeKindMe && record.ScopeValue != "" {
 445→		if idx, exists := byScopeKey[recordScopeKey(record.Fingerprint, record.ScopeKind, "")]; exists {
 446→			return idx, true
 447→		}
 448→	}
 449→
 450→	bestIdx := -1
 451→	bestScore := 0.0
 452→	for i, existing := range records {
 453→		if existing.Kind != record.Kind {
 454→			continue
 455→		}
 456→		if !sameReconcileScope(existing, record) {
 457→			continue
 458→		}
 459→		score := logicalRuleSimilarity(existing, record)
 460→		if score > bestScore {
 461→			bestScore = score
 462→			bestIdx = i
 463→		}
 464→	}
 465→	if bestIdx >= 0 && bestScore >= 0.50 {
 466→		return bestIdx, true
 467→	}
 468→	return -1, false
 469→}
