 471→func logicalRuleSimilarity(a, b MemoryRecord) float64 {
 472→	aTokens := tokenize(strings.Join([]string{a.Title, a.Body}, " "))
 473→	bTokens := tokenize(strings.Join([]string{b.Title, b.Body}, " "))
 474→	if len(aTokens) == 0 || len(bTokens) == 0 {
 475→		return 0
 476→	}
 477→
 478→	intersection := 0
 479→	for token := range aTokens {
 480→		if _, ok := bTokens[token]; ok {
 481→			intersection++
 482→		}
 483→	}
 484→	if intersection < 3 {
 485→		return 0
 486→	}
 487→
 488→	union := len(aTokens)
 489→	for token := range bTokens {
 490→		if _, ok := aTokens[token]; !ok {
 491→			union++
 492→		}
 493→	}
 494→	if union == 0 {
 495→		return 0
 496→	}
 497→
 498→	jaccard := float64(intersection) / float64(union)
 499→	minSize := len(aTokens)
 500→	if len(bTokens) < minSize {
 501→		minSize = len(bTokens)
 502→	}
 503→	if minSize == 0 {
 504→		return 0
 505→	}
 506→	overlapCoeff := float64(intersection) / float64(minSize)
 507→	if overlapCoeff > jaccard {
 508→		return overlapCoeff
 509→	}
 510→	return jaccard
 511→}
