 526→func FormatInjectionBlock(matches []Match) string {
 527→	if len(matches) == 0 {
 528→		return ""
 529→	}
 530→
 531→	var buf bytes.Buffer
 532→	buf.WriteString("Memory For This Repo\n")
 533→	for _, match := range matches {
 534→		buf.WriteString("- ")
 535→		buf.WriteString(strings.TrimSpace(match.Record.Title))
 536→		if body := strings.TrimSpace(match.Record.Body); body != "" {
 537→			buf.WriteString(": ")
 538→			buf.WriteString(body)
 539→		}
 540→		if why := strings.TrimSpace(match.Record.Why); why != "" {
 541→			buf.WriteString(" Why: ")
 542→			buf.WriteString(why)
 543→		}
 544→		buf.WriteByte('\n')
 545→		if buf.Len() >= maxInjectionBytes {
 546→			break
 547→		}
 548→	}
 549→
 550→	out := strings.TrimSpace(buf.String())
 551→	if len(out) > maxInjectionBytes {
 552→		out = out[:maxInjectionBytes]
 553→	}
 554→	return out
 555→}
