 557→func TransitionRecordLifecycle(records []MemoryRecord, id string, action LifecycleAction, now time.Time) ([]MemoryRecord, MemoryRecord, error) {
 558→	updated := append([]MemoryRecord(nil), records...)
 559→	for i := range updated {
 560→		if updated[i].ID != id {
 561→			continue
 562→		}
 563→
 564→		record, err := transitionRecord(updated[i], action, now)
 565→		if err != nil {
 566→			return updated, updated[i], err
 567→		}
 568→		updated[i] = record
 569→		return updated, record, nil
 570→	}
 571→
 572→	return updated, MemoryRecord{}, fmt.Errorf("memory not found: %s", id)
 573→}
