 575→func AddManualRecord(records []MemoryRecord, input ManualRecordInput, now time.Time) ([]MemoryRecord, MemoryRecord, error) {
 576→	if strings.TrimSpace(input.Title) == "" {
 577→		return records, MemoryRecord{}, errors.New("memory title is required")
 578→	}
 579→	if strings.TrimSpace(input.Body) == "" {
 580→		return records, MemoryRecord{}, errors.New("memory body is required")
 581→	}
 582→	if input.Kind == "" {
 583→		return records, MemoryRecord{}, errors.New("memory kind is required")
 584→	}
 585→	if input.ScopeKind == "" {
 586→		input.ScopeKind = ScopeKindMe
 587→	}
 588→
 589→	record := MemoryRecord{
 590→		ID:          makeRecordID(input.Kind, input.Title),
 591→		Kind:        input.Kind,
 592→		Title:       strings.TrimSpace(input.Title),
 593→		Body:        strings.TrimSpace(input.Body),
 594→		Fingerprint: fingerprintForRecord(input.Kind, input.Title, input.Body),
 595→		ScopeKind:   input.ScopeKind,
 596→		ScopeValue:  strings.TrimSpace(input.ScopeValue),
 597→		Origin:      OriginManual,
 598→		OwnerEmail:  strings.TrimSpace(input.OwnerEmail),
 599→		Status:      StatusActive,
 600→		CreatedAt:   now,
 601→		UpdatedAt:   now,
 602→		History: []HistoryEvent{
 603→			{Type: "added", At: now},
 604→		},
 605→	}
 606→
 607→	updated := append([]MemoryRecord(nil), records...)
 608→	if idx, exists := findReconcileIndex(updated, indexRecordScopeKeys(updated), record); exists {
 609→		existing := updated[idx]
 610→		existing.Kind = record.Kind
 611→		existing.Title = record.Title
 612→		existing.Body = record.Body
 613→		existing.Fingerprint = record.Fingerprint
 614→		existing.ScopeKind = record.ScopeKind
 615→		existing.ScopeValue = record.ScopeValue
 616→		existing.Origin = OriginManual
 617→		existing.OwnerEmail = record.OwnerEmail
 618→		existing.Status = StatusActive
 619→		existing.UpdatedAt = now
 620→		existing.LastReviewedAt = now
 621→		existing.History = append(existing.History, HistoryEvent{Type: "added", At: now})
 622→		updated[idx] = existing
 623→		return updated, existing, nil
 624→	}
 625→
 626→	updated = append(updated, record)
 627→	return updated, record, nil
 628→}
