 630→func RecordInjectionActivity(state *State, matches []Match, log InjectionLog, now time.Time) {
 631→	if state == nil || state.Store == nil {
 632→		return
 633→	}
 634→
 635→	matchIDs := make(map[string]struct{}, len(matches))
 636→	for _, match := range matches {
 637→		matchIDs[match.Record.ID] = struct{}{}
 638→	}
 639→
 640→	for i := range state.Store.Records {
 641→		if _, ok := matchIDs[state.Store.Records[i].ID]; !ok {
 642→			continue
 643→		}
 644→		state.Store.Records[i].MatchCount++
 645→		state.Store.Records[i].LastMatchedAt = now
 646→		state.Store.Records[i].History = append(state.Store.Records[i].History, HistoryEvent{
 647→			Type: "matched",
 648→			At:   now,
 649→		})
 650→		state.Store.Records[i].InjectCount++
 651→		state.Store.Records[i].LastInjectedAt = now
 652→		state.Store.Records[i].History = append(state.Store.Records[i].History, HistoryEvent{
 653→			Type: "injected",
 654→			At:   now,
 655→		})
 656→	}
 657→
 658→	state.InjectionLogs = append(state.InjectionLogs, log)
 659→	if len(state.InjectionLogs) > maxInjectionLogs {
