 668→func DeriveOutcomesFromEvidence(records []MemoryRecord, evidence []string, _ time.Time) []MemoryRecord {
 669→	updated := append([]MemoryRecord(nil), records...)
 670→	signalTokens := tokenize(strings.Join(evidence, " "))
 671→
 672→	for i := range updated {
 673→		if updated[i].Origin == OriginManual {
 674→			updated[i].Outcome = OutcomeNeutral
 675→			continue
 676→		}
 677→
 678→		recordTokens := tokenize(strings.Join([]string{updated[i].Title, updated[i].Body, updated[i].Why}, " "))
 679→		overlap := 0
 680→		for token := range recordTokens {
 681→			if _, ok := signalTokens[token]; ok {
 682→				overlap++
 683→			}
 684→		}
 685→
 686→		switch {
 687→		case overlap == 0:
 688→			updated[i].Outcome = OutcomeNeutral
 689→		case updated[i].InjectCount > 0:
 690→			updated[i].Outcome = OutcomeIneffective
 691→		default:
 692→			updated[i].Outcome = OutcomeReinforced
 693→		}
 694→	}
 695→
 696→	return updated
 697→}
