 712→
 713→		updated[i].Status = StatusArchived
 714→		updated[i].UpdatedAt = now
 715→		updated[i].History = append(updated[i].History, HistoryEvent{
 716→			Type:   "pruned",
 717→			At:     now,
 718→			Detail: reason,
 719→		})
 720→		result.ArchivedCount++
 721→	}
 722→
 723→	return updated, result
