 726→func transitionRecord(record MemoryRecord, action LifecycleAction, now time.Time) (MemoryRecord, error) {
 727→	nextStatus, err := nextLifecycleStatus(record, action)
 728→	if err != nil {
 729→		return record, err
 730→	}
 731→
 732→	record.Status = nextStatus
 733→	record.UpdatedAt = now
 734→	record.LastReviewedAt = now
 735→	record.History = append(record.History, HistoryEvent{
 736→		Type: lifecycleHistoryType(action),
 737→		At:   now,
 738→	})
 739→	return record, nil
