 783→func lifecycleHistoryType(action LifecycleAction) string {
 784→	switch action {
 785→	case LifecycleActionActivate:
 786→		return "activated"
 787→	case LifecycleActionPromote:
 788→		return "promoted"
 789→	case LifecycleActionSuppress:
 790→		return "suppressed"
 791→	case LifecycleActionUnsuppress:
 792→		return "unsuppressed"
 793→	case LifecycleActionArchive:
 794→		return "archived"
 795→	default:
 796→		return string(action)
 797→	}
