 841→func pruneReason(record MemoryRecord, now time.Time) string {
 842→	if record.Status == StatusArchived {
 843→		return ""
 844→	}
 845→
 846→	lastActivity := record.UpdatedAt
 847→	for _, candidate := range []time.Time{
 848→		record.CreatedAt,
 849→		record.LastMatchedAt,
 850→		record.LastInjectedAt,
 851→		record.LastReviewedAt,
 852→	} {
 853→		if candidate.After(lastActivity) {
 854→			lastActivity = candidate
 855→		}
 856→	}
 857→
 858→	switch {
 859→	case record.Status == StatusCandidate && !lastActivity.IsZero() && now.Sub(lastActivity) >= 30*24*time.Hour:
 860→		return "stale_candidate"
 861→	case record.Status == StatusActive && record.MatchCount == 0 && !lastActivity.IsZero() && now.Sub(lastActivity) >= 60*24*time.Hour:
 862→		return "stale_unmatched_active"
 863→	case record.Status == StatusActive && record.Outcome == OutcomeIneffective && record.InjectCount >= 3:
 864→		return "ineffective_active"
 865→	default:
 866→		return ""
 867→	}
 868→}
