 58→// runInsights fetches session data from the SQLite cache, refreshing it if stale,
 59→// then computes quality scores and renders output.
 60→func runInsights(ctx context.Context, w io.Writer, last int, agentFilter string, outputJSON bool) error {
 61→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 62→	if err != nil {
 63→		return fmt.Errorf("not in a git repository: %w", err)
 64→	}
 65→	entireDir := filepath.Join(worktreeRoot, paths.EntireDir)
 66→
 67→	idb, err := insightsdb.Open(filepath.Join(entireDir, "insights.db"))
 68→	if err != nil {
 69→		return fmt.Errorf("open insights cache: %w", err)
 70→	}
 71→	defer func() { _ = idb.Close() }()
 72→
 73→	// Non-fatal: continue with whatever is in the cache.
 74→	// If the cache is empty the command will show an empty report.
 75→	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // Non-fatal; continue with stale cache
 76→
 77→	// Generate summaries for recent sessions that lack them.
 78→	backfillSummaries(ctx, w, idb, last)
 79→	backfillFacets(ctx, idb, last)
 80→
 81→	var rows []insightsdb.SessionRow
 82→	if agentFilter != "" {
 83→		rows, err = idb.QueryByAgent(ctx, agentFilter, last)
 84→	} else {
 85→		rows, err = idb.QueryLastNSessions(ctx, last)
 86→	}
 87→	if err != nil {
 88→		return fmt.Errorf("query sessions: %w", err)
 89→	}
 90→
 91→	scores := sessionRowsToScores(rows)
 92→	trends := insights.ComputeTrends(scores)
 93→	comparisons := insights.ComputeAgentComparisons(scores)
 94→
 95→	period := fmt.Sprintf("last %d sessions", last)
 96→	if agentFilter != "" {
 97→		period = fmt.Sprintf("last %d sessions for %s", last, agentFilter)
 98→	}
 99→
100→	report := insights.Report{
101→		GeneratedAt:  time.Now(),
102→		Period:       period,
103→		Sessions:     scores,
104→		Trends:       trends,
105→		Comparisons:  comparisons,
106→		SessionCount: len(scores),
107→	}
108→
109→	if outputJSON {
110→		return renderInsightsJSON(w, report)
111→	}
112→	renderInsightsTerminal(w, report)
113→	return nil
114→}
