116→// refreshCacheIfStale checks whether the insights cache is up-to-date with the
117→// entire/checkpoints/v1 branch and rebuilds it if not.
118→func refreshCacheIfStale(ctx context.Context, idb *insightsdb.InsightsDB) error {
119→	repo, err := openRepository(ctx)
120→	if err != nil {
121→		return fmt.Errorf("open git repository: %w", err)
122→	}
123→
124→	// Resolve the current tip of entire/checkpoints/v1.
125→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
126→	ref, resolveErr := repo.Reference(refName, true)
127→	if resolveErr != nil {
128→		// Branch doesn't exist yet — nothing to cache.
129→		return nil //nolint:nilerr // Missing branch is expected, not an error
130→	}
131→	currentTip := ref.Hash().String()
132→
133→	cachedTip, err := idb.GetBranchTip(ctx)
134→	if err != nil {
135→		return fmt.Errorf("get cached branch tip: %w", err)
136→	}
137→
138→	if cachedTip == currentTip {
139→		return nil // Cache is up-to-date.
140→	}
141→
142→	// Cache is stale — rebuild from git.
143→	store := checkpoint.NewGitStore(repo)
144→	committedList, err := store.ListCommitted(ctx)
145→	if err != nil {
146→		return fmt.Errorf("list committed checkpoints: %w", err)
147→	}
148→
149→	for _, info := range committedList {
150→		cpIDStr := info.CheckpointID.String()
151→
152→		// Check whether we already have this checkpoint cached.
153→		has, hasErr := idb.HasCheckpoint(ctx, cpIDStr)
154→		if hasErr != nil {
155→			return fmt.Errorf("check checkpoint %s: %w", cpIDStr, hasErr)
156→		}
157→		if has {
158→			continue
159→		}
160→
161→		// Read the checkpoint summary to find how many sessions it has.
162→		summary, readErr := store.ReadCommitted(ctx, info.CheckpointID)
163→		if readErr != nil {
164→			continue // Skip unreadable checkpoints; don't abort the whole refresh.
165→		}
166→
167→		for i := range summary.Sessions {
168→			content, contentErr := store.ReadSessionContent(ctx, info.CheckpointID, i)
169→			if contentErr != nil {
170→				continue
171→			}
172→			row := metadataToSessionRow(cpIDStr, i, &content.Metadata)
173→			row.ToolCounts = extractToolCounts(content.Transcript, content.Metadata.Agent)
174→			if insertErr := idb.InsertSession(ctx, row); insertErr != nil {
175→				return fmt.Errorf("insert session %s/%d: %w", cpIDStr, i, insertErr)
176→			}
177→		}
178→	}
179→
180→	if err := idb.SetBranchTip(ctx, currentTip); err != nil {
181→		return fmt.Errorf("set branch tip: %w", err)
182→	}
183→	return nil
184→}
