186→// backfillSummaries generates summaries for the last N sessions that lack them.
187→// It reads transcripts from the checkpoint store, calls Claude to summarize,
188→// and updates the cache. Errors on individual sessions are skipped.
189→func backfillSummaries(ctx context.Context, w io.Writer, idb *insightsdb.InsightsDB, lastN int) {
190→	rows, err := idb.QueryLastNSessions(ctx, lastN)
191→	if err != nil {
192→		return
193→	}
194→
195→	// Filter to sessions without summaries.
196→	var unsummarized []insightsdb.SessionRow
197→	for _, r := range rows {
198→		if !r.HasSummary {
199→			unsummarized = append(unsummarized, r)
200→		}
201→	}
202→	if len(unsummarized) == 0 {
203→		return
204→	}
205→
206→	repo, err := openRepository(ctx)
207→	if err != nil {
208→		return
209→	}
210→	store := checkpoint.NewGitStore(repo)
211→	gen := &summarize.ClaudeGenerator{}
212→
213→	s := termstyle.New(w)
214→	fmt.Fprintf(w, "%s Generating summaries for %d sessions...\n",
215→		s.Render(s.Dim, "i"), len(unsummarized))
216→
217→	generated := 0
218→
219→	for _, row := range unsummarized {
220→		cpID, parseErr := checkpointid.NewCheckpointID(row.CheckpointID)
221→		if parseErr != nil {
222→			continue
223→		}
224→
225→		content, readErr := store.ReadSessionContent(ctx, cpID, row.SessionIndex)
226→		if readErr != nil || len(content.Transcript) == 0 {
227→			continue
228→		}
229→
230→		condensed, buildErr := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
231→		if buildErr != nil || len(condensed) == 0 {
232→			continue
233→		}
234→
235→		input := summarize.Input{
236→			Transcript:   condensed,
237→			FilesTouched: row.FilesTouched,
238→		}
239→		summary, genErr := gen.Generate(ctx, input)
240→		if genErr != nil || summary == nil {
241→			continue
242→		}
243→
244→		// Rebuild the row with summary data.
245→		content.Metadata.Summary = summary
246→		updated := metadataToSessionRow(row.CheckpointID, row.SessionIndex, &content.Metadata)
247→
248→		if updateErr := idb.UpdateSessionSummary(ctx, updated); updateErr != nil {
249→			continue
250→		}
251→
252→		generated++
253→		fmt.Fprintf(w, "  %s %s (%d/%d)\n",
254→			s.Render(s.Green, "✓"), row.CheckpointID[:12], generated, len(unsummarized))
255→	}
256→
257→	if generated > 0 {
258→		fmt.Fprintf(w, "  Generated %d summaries\n\n", generated)
259→	}
260→}
