262→// extractToolCounts parses a transcript and counts tool invocations by name.
263→// Returns nil if the transcript can't be parsed.
264→func extractToolCounts(transcript []byte, agentType types.AgentType) map[string]int {
265→	entries, err := summarize.BuildCondensedTranscriptFromBytes(transcript, agentType)
266→	if err != nil || len(entries) == 0 {
267→		return nil
268→	}
269→	counts := make(map[string]int)
270→	for _, e := range entries {
271→		if e.Type == summarize.EntryTypeTool && e.ToolName != "" {
272→			counts[e.ToolName]++
273→		}
274→	}
275→	if len(counts) == 0 {
276→		return nil
277→	}
278→	return counts
279→}
