281→// metadataToSessionRow converts CommittedMetadata into an insightsdb.SessionRow,
282→// computing quality scores where summary data is available.
283→func metadataToSessionRow(cpID string, sessionIndex int, meta *checkpoint.CommittedMetadata) insightsdb.SessionRow {
284→	row := insightsdb.SessionRow{
285→		CheckpointID: cpID,
286→		SessionID:    meta.SessionID,
287→		SessionIndex: sessionIndex,
288→		Agent:        string(meta.Agent),
289→		Model:        meta.Model,
290→		Branch:       meta.Branch,
291→		OwnerName:    meta.OwnerName,
292→		OwnerEmail:   meta.OwnerEmail,
293→		CreatedAt:    meta.CreatedAt,
294→	}
295→
296→	if meta.TokenUsage != nil {
297→		row.InputTokens = meta.TokenUsage.InputTokens + meta.TokenUsage.CacheCreationTokens + meta.TokenUsage.CacheReadTokens
298→		row.OutputTokens = meta.TokenUsage.OutputTokens
299→		row.TotalTokens = termstyle.TotalTokens(meta.TokenUsage)
300→		row.APICallCount = meta.TokenUsage.APICallCount
301→	}
302→
303→	if meta.SessionMetrics != nil {
304→		row.DurationMs = meta.SessionMetrics.DurationMs
305→		row.TurnCount = meta.SessionMetrics.TurnCount
306→	}
307→
308→	if meta.Summary != nil {
309→		row.HasSummary = true
310→		row.Intent = meta.Summary.Intent
311→		row.Outcome = meta.Summary.Outcome
312→		row.Friction = meta.Summary.Friction
313→
314→		for _, l := range meta.Summary.Learnings.Repo {
315→			row.Learnings = append(row.Learnings, insightsdb.LearningRow{Scope: "repo", Finding: l})
316→		}
317→		for _, l := range meta.Summary.Learnings.Workflow {
318→			row.Learnings = append(row.Learnings, insightsdb.LearningRow{Scope: "workflow", Finding: l})
319→		}
320→		for _, l := range meta.Summary.Learnings.Code {
321→			row.Learnings = append(row.Learnings, insightsdb.LearningRow{Scope: "code", Finding: l.Finding, Path: l.Path})
322→		}
323→	}
324→
325→	// Always compute scores — token efficiency and focus work without summaries.
326→	// Friction/first-pass default to neutral when no summary exists.
327→	data := insights.SessionData{
328→		TotalTokens:   row.TotalTokens,
329→		FilesCount:    len(meta.FilesTouched),
330→		FrictionCount: len(row.Friction),
331→		TurnCount:     row.TurnCount,
332→		HasSummary:    row.HasSummary,
333→	}
334→	if meta.Summary != nil {
335→		data.OpenItemCount = len(meta.Summary.OpenItems)
336→	}
337→	breakdown := insights.ScoreSession(data)
338→	row.OverallScore = insights.ComputeOverall(breakdown)
339→	row.ScoreTokenEff = breakdown.TokenEfficiency
340→	row.ScoreFirstPass = breakdown.FirstPassSuccess
341→	row.ScoreFriction = breakdown.FrictionScore
342→	row.ScoreFocus = breakdown.FocusScore
343→
344→	row.FilesTouched = meta.FilesTouched
345→	return row
346→}
