348→// sessionRowsToScores converts database rows into insights.SessionScore values.
349→func sessionRowsToScores(rows []insightsdb.SessionRow) []insights.SessionScore {
350→	scores := make([]insights.SessionScore, 0, len(rows))
351→	for _, r := range rows {
352→		scores = append(scores, insights.SessionScore{
353→			CheckpointID: r.CheckpointID,
354→			SessionID:    r.SessionID,
355→			Agent:        types.AgentType(r.Agent),
356→			Model:        r.Model,
357→			CreatedAt:    r.CreatedAt,
358→			Overall:      r.OverallScore,
359→			Breakdown: insights.ScoreBreakdown{
360→				TokenEfficiency:  r.ScoreTokenEff,
361→				FirstPassSuccess: r.ScoreFirstPass,
362→				FrictionScore:    r.ScoreFriction,
363→				FocusScore:       r.ScoreFocus,
364→			},
365→			TokensUsed:    r.TotalTokens,
366→			TurnCount:     r.TurnCount,
367→			FilesCount:    len(r.FilesTouched),
368→			FrictionCount: len(r.Friction),
369→			HasSummary:    r.HasSummary,
370→			ToolCallCount: totalToolCalls(r.ToolCounts),
371→			TopTools:      topToolNames(r.ToolCounts, 3),
372→			SkillsUsed:    skillNames(r.ToolCounts),
373→		})
374→	}
375→	return scores
376→}
