378→func totalToolCalls(counts map[string]int) int {
379→	total := 0
380→	for _, c := range counts {
381→		total += c
382→	}
383→	return total
384→}
385→
386→func topToolNames(counts map[string]int, n int) []string {
387→	if len(counts) == 0 {
388→		return nil
389→	}
390→	type kv struct {
391→		name  string
392→		count int
393→	}
394→	sorted := make([]kv, 0, len(counts))
395→	for k, v := range counts {
396→		if k == "Skill" {
397→			continue // skills shown separately
398→		}
399→		sorted = append(sorted, kv{k, v})
400→	}
401→	// Simple selection sort for small N.
402→	for i := range min(n, len(sorted)) {
403→		for j := i + 1; j < len(sorted); j++ {
404→			if sorted[j].count > sorted[i].count {
405→				sorted[i], sorted[j] = sorted[j], sorted[i]
406→			}
407→		}
408→	}
409→	limit := min(n, len(sorted))
410→	names := make([]string, limit)
411→	for i := range limit {
412→		names[i] = sorted[i].name
413→	}
414→	return names
415→}
