417→func skillNames(counts map[string]int) []string {
418→	// Skill tool calls are counted under "Skill" in tool counts.
419→	// We can't distinguish individual skill names from counts alone,
420→	// so we just indicate whether skills were used.
421→	if counts["Skill"] > 0 {
422→		return []string{fmt.Sprintf("%d invocations", counts["Skill"])}
423→	}
424→	return nil
425→}
