437→// renderInsightsTerminal writes a styled terminal view of the insights report.
438→func renderInsightsTerminal(w io.Writer, report insights.Report) {
439→	s := termstyle.New(w)
440→
441→	fmt.Fprintln(w, s.Render(s.Bold, "Entire Insights"))
442→	fmt.Fprintf(w, "Period: %s\n\n", report.Period)
443→
444→	// Session Scores section.
445→	fmt.Fprintln(w, s.SectionRule("Session Scores"))
446→	if len(report.Sessions) == 0 {
447→		fmt.Fprintln(w, "  No sessions found.")
448→	}
449→	for _, ss := range report.Sessions {
450→		shortID := ss.SessionID
451→		if len(shortID) > 12 {
452→			shortID = shortID[:12]
453→		}
454→		scoreLine := fmt.Sprintf("  %5.1f  %s  %s",
455→			ss.Overall,
456→			string(ss.Agent),
457→			shortID,
458→		)
459→		fmt.Fprintln(w, s.Render(s.Bold, scoreLine))
460→
461→		breakdownLine := fmt.Sprintf("  Token Efficiency: %.0f  First-Pass: %.0f  Friction: %.0f  Focus: %.0f",
462→			ss.Breakdown.TokenEfficiency,
463→			ss.Breakdown.FirstPassSuccess,
464→			ss.Breakdown.FrictionScore,
465→			ss.Breakdown.FocusScore,
466→		)
467→		fmt.Fprintln(w, s.Render(s.Dim, breakdownLine))
468→
469→		statsLine := fmt.Sprintf("  %s tokens  %d turns  %d files  %d friction",
470→			termstyle.FormatTokenCount(ss.TokensUsed),
471→			ss.TurnCount,
472→			ss.FilesCount,
473→			ss.FrictionCount,
474→		)
475→		if !ss.HasSummary {
476→			statsLine += "  (no summary)"
477→		}
478→		fmt.Fprintln(w, s.Render(s.Gray, statsLine))
479→
480→		if len(ss.TopTools) > 0 {
481→			toolsLine := "  Tools: " + strings.Join(ss.TopTools, ", ")
482→			if len(ss.SkillsUsed) > 0 {
483→				toolsLine += "  Skills: " + strings.Join(ss.SkillsUsed, ", ")
484→			}
485→			fmt.Fprintln(w, s.Render(s.Gray, toolsLine))
486→		}
487→		fmt.Fprintln(w)
488→	}
489→
490→	// Trends section.
491→	fmt.Fprintln(w, s.SectionRule("Trends"))
492→	for _, t := range report.Trends {
493→		arrow := "→"
494→		style := s.Gray
495→		dirLabel := "stable"
496→		switch t.Direction {
497→		case "improving":
498→			arrow = "↑"
499→			style = s.Green
500→			dirLabel = fmt.Sprintf("+%.1f%%", t.ChangePercent)
501→		case "declining":
502→			arrow = "↓"
503→			style = s.Red
504→			dirLabel = fmt.Sprintf("-%.1f%%", t.ChangePercent)
505→		}
506→		line := fmt.Sprintf("  %s %s (%s)", arrow, t.Metric, dirLabel)
507→		fmt.Fprintln(w, s.Render(style, line))
508→	}
509→	fmt.Fprintln(w)
510→
511→	// Agent Comparison section.
512→	fmt.Fprintln(w, s.SectionRule("Agent Comparison"))
513→	if len(report.Comparisons) == 0 {
514→		fmt.Fprintln(w, "  Not enough data for comparison.")
