183→// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
184→// ensures strategy setup, initializes session.
185→func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
186→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
187→	logging.Info(logCtx, "turn-start",
188→		slog.String("event", event.Type.String()),
189→		slog.String("session_id", event.SessionID),
190→		slog.String("session_ref", event.SessionRef),
191→		slog.String("model", event.Model),
192→	)
193→
194→	sessionID := event.SessionID
195→	if sessionID == "" {
196→		return fmt.Errorf("no session_id in %s event", event.Type)
197→	}
198→	if err := validation.ValidateSessionID(sessionID); err != nil {
199→		return fmt.Errorf("invalid %s event: %w", event.Type, err)
200→	}
201→
202→	// Fill model from hint file if the agent didn't provide it on this hook
203→	if event.Model == "" {
204→		if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
205→			event.Model = hint
206→			logging.Debug(logCtx, "loaded model from hint file",
207→				slog.String("model", hint))
208→		}
209→	}
210→
211→	// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
212→	_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
213→	if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
214→		captureSpan.RecordError(err)
215→		captureSpan.End()
216→		return err
217→	}
218→	captureSpan.End()
219→
220→	// Append prompt to prompt.txt on filesystem so it's available for
221→	// mid-turn commits (before SaveStep writes it to the shadow branch).
222→	// Prompts are separated by "\n\n---\n\n" to support multiple turns.
223→	if event.Prompt != "" {
224→		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
225→		if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
226→			if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
227→				promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
228→				existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
229→				var content string
230→				if readErr == nil && len(existing) > 0 {
231→					content = string(existing) + "\n\n---\n\n" + event.Prompt
232→				} else {
233→					content = event.Prompt
234→				}
235→				if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
236→					logging.Warn(logCtx, "failed to write prompt.txt",
237→						slog.String("error", writeErr.Error()))
238→				}
239→			}
240→		}
241→	}
242→
243→	// Ensure strategy setup and initialize session
244→	_, initSpan := perf.Start(ctx, "init_session")
245→	if err := strategy.EnsureSetup(ctx); err != nil {
246→		logging.Warn(logCtx, "failed to ensure strategy setup",
247→			slog.String("error", err.Error()))
248→	}
249→
250→	strat := GetStrategy(ctx)
251→	if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
252→		logging.Warn(logCtx, "failed to initialize session state",
253→			slog.String("error", err.Error()))
254→	}
255→	initSpan.End()
256→
257→	if err := maybeInjectMemoryLoop(ctx, ag, event); err != nil {
258→		return err
259→	}
260→
261→	return nil
262→}
