264→func maybeInjectMemoryLoop(ctx context.Context, ag agent.Agent, event *agent.Event) error {
265→	if string(ag.Name()) != memoryLoopClaudeAgentName || event.Prompt == "" {
266→		return nil
267→	}
268→
269→	writer, ok := agent.AsHookResponseWriter(ag)
270→	if !ok {
271→		return nil
272→	}
273→
274→	state, loadErr := memoryloop.LoadState(ctx)
275→	if loadErr != nil {
276→		state = &memoryloop.State{}
277→	}
278→	settingsValue, settingsErr := LoadEntireSettings(ctx)
279→	if settingsErr != nil {
280→		settingsValue = nil
281→	}
282→	if effectiveMemoryLoopMode(state, settingsValue) != memoryloop.ModeAuto {
283→		return nil
284→	}
285→
286→	if state.Snapshot == nil || !state.Snapshot.InjectionEnabled {
287→		return nil
288→	}
289→
290→	now := time.Now().UTC()
291→	matches := memoryloop.SelectRelevant(*state.Snapshot, event.Prompt, now)
292→	if len(matches) == 0 {
293→		return nil
294→	}
295→
296→	message := memoryloop.FormatInjectionBlock(matches)
297→	if strings.TrimSpace(event.ResponseMessage) != "" {
298→		message = strings.TrimSpace(event.ResponseMessage) + "\n\n" + message
299→	}

