 45→func (g *Generator) Generate(ctx context.Context, input GenerateInput) ([]MemoryRecord, *llmcli.UsageInfo, error) {
 46→	if g.Runner == nil {
 47→		g.Runner = &llmcli.Runner{}
 48→	}
 49→
 50→	if input.MaxRecords <= 0 {
 51→		input.MaxRecords = DefaultMaxRecords
 52→	}
 53→
 54→	raw, usage, err := g.Runner.Execute(ctx, BuildPrompt(input))
 55→	if err != nil {
 56→		return nil, nil, fmt.Errorf("execute memory-loop prompt: %w", err)
 57→	}
 58→
 59→	var resp generateResponse
 60→	if err := json.Unmarshal([]byte(raw), &resp); err != nil {
 61→		return nil, nil, fmt.Errorf("parse memory-loop JSON: %w", err)
 62→	}
 63→
 64→	return buildGeneratedRecords(resp, input, time.Now().UTC()), usage, nil
 65→}
