 67→func buildGeneratedRecords(resp generateResponse, input GenerateInput, now time.Time) []MemoryRecord {
 68→	seen := make(map[string]struct{})
 69→	records := make([]MemoryRecord, 0, len(resp.Records))
 70→	for _, item := range resp.Records {
 71→		title := strings.TrimSpace(item.Title)
 72→		body := strings.TrimSpace(item.Body)
 73→		if title == "" || body == "" {
 74→			continue
 75→		}
 76→		kind := item.Kind
 77→		if kind == "" {
 78→			kind = KindRepoRule
 79→		}
 80→		key := strings.ToLower(string(kind) + "|" + title + "|" + body)
 81→		if _, ok := seen[key]; ok {
 82→			continue
 83→		}
 84→		seen[key] = struct{}{}
 85→
 86→		record := MemoryRecord{
 87→			ID:               makeRecordID(kind, title),
 88→			Kind:             kind,
 89→			Title:            title,
 90→			Body:             body,
 91→			Why:              strings.TrimSpace(item.Why),
 92→			Evidence:         trimSlice(item.Evidence, 3),
 93→			SourceSessionIDs: trimSlice(item.SourceSessionIDs, input.SourceWindow),
 94→			Confidence:       normalizeConfidence(item.Confidence),
 95→			Strength:         clamp(item.Strength, 1, 5),
 96→			Status:           StatusCandidate,
 97→			Origin:           OriginGenerated,
 98→			Fingerprint:      fingerprintForRecord(kind, title, body),
 99→			CreatedAt:        now,
100→			UpdatedAt:        now,
101→		}
102→		records = append(records, record)
103→		if len(records) >= input.MaxRecords {
104→			break
105→		}
106→	}
107→
108→	return records
109→}
