1023→func filterMemoryLoopRows(rows []insightsdb.SessionRow, scope memoryLoopScope, limit int) ([]insightsdb.SessionRow, error) {
1024→	filtered := make([]insightsdb.SessionRow, 0, len(rows))
1025→	for _, row := range rows {
1026→		switch scope.Mode {
1027→		case memoryLoopScopeRepo:
1028→			filtered = append(filtered, row)
1029→		case memoryLoopScopeBranch:
1030→			if row.Branch == scope.Branch {
1031→				filtered = append(filtered, row)
1032→			}
1033→		case memoryLoopScopeMe:
1034→			if strings.EqualFold(row.OwnerEmail, scope.OwnerEmail) {
1035→				filtered = append(filtered, row)
1036→			}
1037→		default:
1038→			return nil, fmt.Errorf("unsupported scope mode %q", scope.Mode)
1039→		}
1040→	}
1041→
1042→	sort.SliceStable(filtered, func(i, j int) bool {
1043→		return filtered[i].CreatedAt.After(filtered[j].CreatedAt)
1044→	})
1045→	if limit > 0 && len(filtered) > limit {
1046→		filtered = filtered[:limit]
1047→	}
1048→	return filtered, nil
