171→// parseSubStepKey checks if a step name like "foo.0" is a sub-step of "foo".
172→// Returns the parent name, index, and true if it is a sub-step.
173→// A name is a sub-step if: the last segment after the final "." is a non-negative
174→// integer AND the parent name exists in allSteps.
175→func parseSubStepKey(name string, allSteps map[string]int64) (string, int, bool) {
176→	lastDot := strings.LastIndex(name, ".")
177→	if lastDot < 0 {
178→		return "", 0, false
179→	}
180→	parent := name[:lastDot]
181→	suffix := name[lastDot+1:]
182→	idx, err := strconv.Atoi(suffix)
183→	if err != nil || idx < 0 {
184→		return "", 0, false
185→	}
186→	if _, exists := allSteps[parent]; !exists {
187→		return "", 0, false
188→	}
189→	return parent, idx, true
190→}
