 58→// runImprove fetches session data from the SQLite cache, refreshes it if stale,
 59→// then analyzes friction patterns and optionally generates context file improvements.
 60→func runImprove(ctx context.Context, w io.Writer, last int, dryRun bool, outputJSON bool) error {
 61→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 62→	if err != nil {
 63→		return fmt.Errorf("not in a git repository: %w", err)
 64→	}
 65→	entireDir := filepath.Join(worktreeRoot, paths.EntireDir)
 66→
 67→	idb, err := insightsdb.Open(filepath.Join(entireDir, "insights.db"))
 68→	if err != nil {
 69→		return fmt.Errorf("open insights cache: %w", err)
 70→	}
 71→	defer func() { _ = idb.Close() }()
 72→
 73→	// Non-fatal: continue with whatever is in the cache.
 74→	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // Non-fatal; continue with stale cache
 75→
 76→	// Generate summaries for recent sessions that lack them.
 77→	if !dryRun {
 78→		backfillSummaries(ctx, w, idb, last)
 79→		backfillFacets(ctx, idb, last)
 80→	}
 81→
 82→	// Fetch the last N sessions for summary stats.
 83→	rows, err := idb.QueryLastNSessions(ctx, last)
 84→	if err != nil {
 85→		return fmt.Errorf("query sessions: %w", err)
 86→	}
 87→
 88→	// Count total friction items across all sessions.
 89→	frictionTotal := 0
 90→	for _, r := range rows {
 91→		frictionTotal += len(r.Friction)
 92→	}
 93→
 94→	// Use keyword-based theme classification for pattern detection.
 95→	// This groups friction by theme (lint, api, conflict, etc.) instead of exact text match.
 96→	summaries := sessionRowsToSummaries(rows)
 97→	analysis := improve.AnalyzePatterns(summaries)
 98→
 99→	if dryRun {
100→		if outputJSON {
101→			return renderImproveJSONDryRunThemes(w, analysis, len(rows), frictionTotal)
102→		}
103→		renderImproveTerminalDryRun(w, analysis, len(rows), frictionTotal)
104→		return nil
105→	}
106→
107→	// Deep-read transcripts for top friction themes.
108→	if err = attachTranscriptExcerpts(ctx, idb, analysis.RepeatedFriction, worktreeRoot); err != nil {
109→		_ = err // Non-fatal: proceed without transcript excerpts.
110→	}
111→
112→	// Detect context files.
113→	contextFiles := improve.DetectContextFiles(worktreeRoot)
114→
115→	gen := improve.Generator{Runner: &llmcli.Runner{}}
116→	result, err := gen.Generate(ctx, analysis, contextFiles)
117→	if err != nil {
118→		return fmt.Errorf("generate suggestions: %w", err)
119→	}
120→
121→	report := improve.ImprovementReport{
122→		ContextFiles:  contextFiles,
123→		Suggestions:   result.Suggestions,
124→		Facets:        facetSummary(analysis),
125→		FacetCounts:   facetCounts(analysis),
126→		SessionsUsed:  len(rows),
127→		FrictionTotal: frictionTotal,
128→		PatternsFound: analysisPatternCount(analysis),
129→	}
130→
131→	if outputJSON {
132→		return renderImproveJSON(w, report)
133→	}
134→	renderImproveTerminal(w, report)
135→	if result.Usage != nil {
136→		renderUsageLine(w, result.Usage)
137→	}
138→	return nil
139→}
