141→// attachTranscriptExcerpts fetches transcript excerpts for top friction patterns and
142→// attaches them in-place. Uses the pattern's AffectedSessions to find relevant checkpoints.
143→// Errors are non-fatal; unreadable sessions are silently skipped.
144→func attachTranscriptExcerpts(ctx context.Context, _ *insightsdb.InsightsDB, patterns []improve.FrictionPattern, _ string) error {
145→	repo, err := openRepository(ctx)
146→	if err != nil {
147→		return fmt.Errorf("open git repository: %w", err)
148→	}
149→	store := checkpoint.NewGitStore(repo)
150→
151→	// Limit to top 3 friction themes.
152→	limit := 3
153→	if len(patterns) < limit {
154→		limit = len(patterns)
155→	}
156→
157→	for i := range patterns[:limit] {
158→		cpIDs := patterns[i].AffectedSessions
159→
160→		// Limit to top 2 sessions per theme.
161→		sessionLimit := 2
162→		if len(cpIDs) < sessionLimit {
163→			sessionLimit = len(cpIDs)
164→		}
165→
166→		var excerpts []string
167→		for _, cpIDStr := range cpIDs[:sessionLimit] {
168→			cpID, parseErr := checkpointid.NewCheckpointID(cpIDStr)
169→			if parseErr != nil {
170→				continue
171→			}
172→
173→			content, readErr := store.ReadSessionContent(ctx, cpID, 0)
174→			if readErr != nil {
175→				continue
176→			}
177→
178→			condensed, buildErr := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
179→			if buildErr != nil || len(condensed) == 0 {
180→				continue
181→			}
182→
183→			formatted := summarize.FormatCondensedTranscript(summarize.Input{Transcript: condensed})
184→			excerpt := truncateString(formatted, 2000)
185→			if excerpt != "" {
186→				excerpts = append(excerpts, excerpt)
187→			}
188→		}
189→
190→		if len(excerpts) > 0 {
191→			patterns[i].TranscriptExcerpt = strings.Join(excerpts, "\n---\n")
192→		}
193→	}
194→
195→	return nil
196→}
