198→// sessionRowsToSummaries converts insightsdb rows into improve.SessionSummaryData values.
199→func sessionRowsToSummaries(rows []insightsdb.SessionRow) []improve.SessionSummaryData {
200→	summaries := make([]improve.SessionSummaryData, 0, len(rows))
201→	for _, r := range rows {
202→		s := improve.SessionSummaryData{
203→			CheckpointID: r.CheckpointID,
204→			Friction:     r.Friction,
205→			Facets:       r.Facets,
206→		}
207→		for _, l := range r.Learnings {
208→			s.Learnings = append(s.Learnings, improve.LearningEntry{
209→				Scope:   l.Scope,
210→				Finding: l.Finding,
211→				Path:    l.Path,
212→			})
213→		}
214→		summaries = append(summaries, s)
215→	}
216→	return summaries
217→}
