383→// renderDiff writes a unified diff with colored lines to w.
384→// Lines starting with '+' are rendered in green, '-' in red, '@@' in cyan,
385→// and all other lines in dim.
386→func renderDiff(w io.Writer, s termstyle.Styles, diff string) {
387→	for _, line := range strings.Split(diff, "\n") {
388→		switch {
389→		case strings.HasPrefix(line, "@@"):
390→			fmt.Fprintln(w, s.Render(s.Cyan, line))
391→		case strings.HasPrefix(line, "+"):
392→			fmt.Fprintln(w, s.Render(s.Green, line))
393→		case strings.HasPrefix(line, "-"):
394→			fmt.Fprintln(w, s.Render(s.Red, line))
395→		default:
396→			fmt.Fprintln(w, s.Render(s.Dim, line))
397→		}
398→	}
399→}
