250→func runMemoryLoopRefresh(ctx context.Context, w io.Writer, last int, scopeArg, branchArg string) error {
251→	worktreeRoot, err := paths.WorktreeRoot(ctx)
252→	if err != nil {
253→		return fmt.Errorf("not in a git repository: %w", err)
254→	}
255→
256→	cfg, cfgErr := LoadEntireSettings(ctx)
257→	if cfgErr != nil {
258→		return fmt.Errorf("load settings: %w", cfgErr)
259→	}
260→
261→	idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
262→	if err != nil {
263→		return fmt.Errorf("open insights cache: %w", err)
264→	}
265→	defer func() { _ = idb.Close() }()
266→
267→	renderMemoryLoopRefreshProgress(w, "Refreshing cache...")
268→	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // non-fatal
269→	if settings.IsSummarizeEnabled(ctx) {
270→		renderMemoryLoopRefreshProgress(w, "Backfilling summaries...")
271→		backfillSummaries(ctx, w, idb, last)
272→		renderMemoryLoopRefreshProgress(w, "Backfilling facets...")
273→		backfillFacets(ctx, idb, last)
274→	}
275→
276→	scope, err := resolveMemoryLoopScope(ctx, scopeArg, branchArg)
277→	if err != nil {
278→		return err
279→	}
280→
281→	renderMemoryLoopRefreshProgress(w, "Loading scoped sessions...")
282→	rows, err := queryMemoryLoopRows(ctx, idb, scope, last)
283→	if err != nil {
284→		return fmt.Errorf("query sessions: %w", err)
285→	}
286→
287→	analysis := improve.AnalyzePatterns(sessionRowsToSummaries(rows))
288→	gen := memoryloop.Generator{Runner: &llmcli.Runner{}}
289→	renderMemoryLoopRefreshProgress(w, "Distilling memories...")
290→	records, usage, err := gen.Generate(ctx, memoryloop.GenerateInput{
291→		Analysis:     analysis,
292→		Sessions:     rows,
293→		SourceWindow: last,
294→		MaxRecords:   memoryloop.DefaultMaxRecords,
295→	})
296→	if err != nil {
297→		return fmt.Errorf("generate memory snapshot: %w", err)
298→	}
299→
300→	state, err := memoryloop.LoadState(ctx)
301→	if err != nil {
302→		return fmt.Errorf("load memory-loop state: %w", err)
303→	}
304→
305→	memoryCfg := cfg.GetMemoryLoopConfig()
306→	maxInjected := memoryCfg.MaxInjected
307→	mode := memoryloop.Mode(memoryCfg.Mode)
308→	activationPolicy := memoryloop.ActivationPolicy(memoryCfg.ActivationPolicy)
309→	if state.Store != nil {
310→		if state.Store.Mode != "" {
311→			mode = state.Store.Mode
312→		}
313→		if state.Store.MaxInjected > 0 {
314→			maxInjected = state.Store.MaxInjected
315→		}
316→		if state.Store.ActivationPolicy != "" {
317→			activationPolicy = state.Store.ActivationPolicy
318→		}
319→	}
320→
321→	now := time.Now().UTC()
322→	scopeValue := scopeValue(scope)
323→	renderMemoryLoopRefreshProgress(w, "Reconciling with existing memory history...")
324→	reconcile := memoryloop.ReconcileGeneratedRecords(
325→		existingMemoryRecords(state),
326→		records,
327→		scopeKindForRefresh(scope),
328→		scopeValue,
329→		activationPolicy,
330→		now,
331→	)
332→	reconcile.History.Scope = string(scope.Mode)
333→	reconcile.History.SourceWindow = last
334→	refreshHistory := append(existingRefreshHistory(state), reconcile.History)
335→	reconciledRecords := memoryloop.DeriveOutcomes(reconcile.Records, rows, now)
336→
337→	state.Store = &memoryloop.Store{
338→		Version:          1,
339→		GeneratedAt:      now,
340→		SourceWindow:     last,
341→		Scope:            string(scope.Mode),
342→		ScopeValue:       scopeValue,
343→		Records:          reconciledRecords,
344→		Mode:             mode,
345→		ActivationPolicy: activationPolicy,
346→		MaxInjected:      maxInjected,
347→		RefreshHistory:   refreshHistory,
348→	}
