 436→func recordScopeKey(fingerprint string, scopeKind ScopeKind, scopeValue string) string {
 437→	return strings.Join([]string{fingerprint, string(scopeKind), scopeValue}, "|")
 438→}
 439→
 440→func findReconcileIndex(records []MemoryRecord, byScopeKey map[string]int, record MemoryRecord) (int, bool) {
 441→	if idx, exists := byScopeKey[recordScopeKey(record.Fingerprint, record.ScopeKind, record.ScopeValue)]; exists {
 442→		return idx, true
 443→	}
 444→	if record.ScopeKind == ScopeKindMe && record.ScopeValue != "" {
 445→		if idx, exists := byScopeKey[recordScopeKey(record.Fingerprint, record.ScopeKind, "")]; exists {
 446→			return idx, true
 447→		}
 448→	}
 449→
 450→	bestIdx := -1
 451→	bestScore := 0.0
 452→	for i, existing := range records {
 453→		if existing.Kind != record.Kind {
 454→			continue
 455→		}
 456→		if !sameReconcileScope(existing, record) {
 457→			continue
 458→		}
 459→		score := logicalRuleSimilarity(existing, record)
 460→		if score > bestScore {
 461→			bestScore = score
 462→			bestIdx = i
 463→		}
 464→	}
 465→	if bestIdx >= 0 && bestScore >= 0.50 {
 466→		return bestIdx, true
 467→	}
 468→	return -1, false
 469→}
 470→
 471→func logicalRuleSimilarity(a, b MemoryRecord) float64 {
 472→	aTokens := tokenize(strings.Join([]string{a.Title, a.Body}, " "))
 473→	bTokens := tokenize(strings.Join([]string{b.Title, b.Body}, " "))
 474→	if len(aTokens) == 0 || len(bTokens) == 0 {
 475→		return 0
 476→	}
 477→
 478→	intersection := 0
 479→	for token := range aTokens {
 480→		if _, ok := bTokens[token]; ok {
 481→			intersection++
 482→		}
 483→	}
 484→	if intersection < 3 {
 485→		return 0
 486→	}
 487→
 488→	union := len(aTokens)
 489→	for token := range bTokens {
 490→		if _, ok := aTokens[token]; !ok {
 491→			union++
 492→		}
 493→	}
 494→	if union == 0 {
 495→		return 0
 496→	}
 497→
 498→	jaccard := float64(intersection) / float64(union)
 499→	minSize := len(aTokens)
 500→	if len(bTokens) < minSize {
 501→		minSize = len(bTokens)
 502→	}
 503→	if minSize == 0 {
 504→		return 0
 505→	}
 506→	overlapCoeff := float64(intersection) / float64(minSize)
 507→	if overlapCoeff > jaccard {
 508→		return overlapCoeff
 509→	}
 510→	return jaccard
 511→}
