 513→func sameReconcileScope(a, b MemoryRecord) bool {
 514→	if a.ScopeKind != b.ScopeKind {
 515→		return false
 516→	}
 517→	if a.ScopeValue == b.ScopeValue {
 518→		return true
 519→	}
 520→	if a.ScopeKind == ScopeKindMe && (a.ScopeValue == "" || b.ScopeValue == "") {
 521→		return true
 522→	}
 523→	return false
 524→}
