 726→func transitionRecord(record MemoryRecord, action LifecycleAction, now time.Time) (MemoryRecord, error) {
 727→	nextStatus, err := nextLifecycleStatus(record, action)
 728→	if err != nil {
 729→		return record, err
 730→	}
 731→
 732→	record.Status = nextStatus
 733→	record.UpdatedAt = now
 734→	record.LastReviewedAt = now
 735→	record.History = append(record.History, HistoryEvent{
 736→		Type: lifecycleHistoryType(action),
 737→		At:   now,
 738→	})
 739→	return record, nil
 740→}
 741→
 742→func nextLifecycleStatus(record MemoryRecord, action LifecycleAction) (Status, error) {
 743→	switch action {
 744→	case LifecycleActionActivate:
 745→		if record.ScopeKind == ScopeKindRepo {
 746→			return record.Status, fmt.Errorf("repo-scoped memory %q requires promote, not activate", record.ID)
 747→		}
 748→		if record.Status == StatusSuppressed {
 749→			return record.Status, fmt.Errorf("memory %q is suppressed; use unsuppress first", record.ID)
 750→		}
 751→		if record.Status == StatusArchived {
 752→			return record.Status, fmt.Errorf("memory %q is archived", record.ID)
 753→		}
 754→		return StatusActive, nil
 755→	case LifecycleActionPromote:
 756→		if record.ScopeKind != ScopeKindRepo {
 757→			return record.Status, fmt.Errorf("memory %q is not repo-scoped", record.ID)
 758→		}
 759→		if record.Status == StatusSuppressed {
 760→			return record.Status, fmt.Errorf("memory %q is suppressed; use unsuppress first", record.ID)
 761→		}
 762→		if record.Status == StatusArchived {
 763→			return record.Status, fmt.Errorf("memory %q is archived", record.ID)
 764→		}
 765→		return StatusActive, nil
 766→	case LifecycleActionSuppress:
 767→		if record.Status == StatusArchived {
 768→			return record.Status, fmt.Errorf("memory %q is archived", record.ID)
 769→		}
 770→		return StatusSuppressed, nil
 771→	case LifecycleActionUnsuppress:
 772→		if record.Status != StatusSuppressed {
 773→			return record.Status, fmt.Errorf("memory %q is not suppressed", record.ID)
 774→		}
 775→		return StatusCandidate, nil
 776→	case LifecycleActionArchive:
 777→		return StatusArchived, nil
 778→	default:
 779→		return record.Status, fmt.Errorf("unsupported lifecycle action: %s", action)
 780→	}
 781→}
