 813→func buildOutcomeSignalText(sessions []insightsdb.SessionRow) string {
 814→	parts := make([]string, 0, len(sessions)*4)
 815→	for _, session := range sessions {
 816→		parts = append(parts, session.Friction...)
 817→		for _, learning := range session.Learnings {
 818→			parts = append(parts, learning.Finding)
 819→		}
 820→		parts = append(parts, session.Facets.RepoGotchas...)
 821→		parts = append(parts, session.Facets.WorkflowGaps...)
 822→		for _, item := range session.Facets.MissingContext {
 823→			parts = append(parts, item.Item)
 824→		}
 825→		for _, item := range session.Facets.RepeatedUserInstructions {
 826→			parts = append(parts, item.Instruction)
 827→		}
 828→		for _, item := range session.Facets.FailureLoops {
 829→			parts = append(parts, item.Description)
 830→		}
 831→		for _, item := range session.Facets.SkillSignals {
 832→			parts = append(parts, item.Friction...)
 833→			if item.MissingInstruction != "" {
 834→				parts = append(parts, item.MissingInstruction)
 835→			}
 836→		}
 837→	}
 838→	return strings.Join(parts, " ")
 839→}
