 874→func normalizeStateWithSource(state *State, loadedFromLegacySnapshot bool) {
 875→	if state == nil {
 876→		return
 877→	}
 878→	loadedFromLegacySnapshot = loadedFromLegacySnapshot || (state.Store == nil && state.Snapshot != nil)
 879→	switch {
 880→	case state.Store == nil && state.Snapshot != nil:
 881→		state.Store = state.Snapshot
 882→	case state.Store != nil && state.Snapshot == nil:
 883→		state.Snapshot = state.Store
 884→	}
 885→	if state.Store == nil {
 886→		return
 887→	}
 888→
 889→	if state.Store.Version == 0 {
 890→		state.Store.Version = 1
 891→	}
 892→	if state.Store.MaxInjected <= 0 {
 893→		state.Store.MaxInjected = DefaultMaxInjected
 894→	}
 895→	if state.Store.SourceWindow <= 0 {
 896→		state.Store.SourceWindow = DefaultRefreshWindow
 897→	}
 898→	if state.Store.Mode == "" {
 899→		if state.Store.InjectionEnabled {
 900→			state.Store.Mode = ModeAuto
 901→		} else {
 902→			state.Store.Mode = ModeManual
 903→		}
 904→	}
 905→	state.Store.InjectionEnabled = state.Store.Mode == ModeAuto
 906→	if state.Store.ActivationPolicy == "" {
 907→		state.Store.ActivationPolicy = ActivationPolicyReview
 908→	}
 909→	for i := range state.Store.Records {
 910→		record := &state.Store.Records[i]
 911→		inferred := false
 912→		if record.Status == "" {
 913→			record.Status = StatusActive
 914→			inferred = true
 915→		}
 916→		if record.Origin == "" {
 917→			record.Origin = OriginGenerated
 918→			inferred = true
 919→		}
 920→		if record.ScopeKind == "" {
 921→			record.ScopeKind = ScopeKindMe
 922→			inferred = true
 923→		}
 924→		if record.Outcome == "" {
 925→			record.Outcome = OutcomeNeutral
 926→			inferred = true
 927→		}
 928→		if record.Fingerprint == "" {
 929→			record.Fingerprint = fingerprintForRecord(record.Kind, record.Title, record.Body)
 930→		}
 931→		if loadedFromLegacySnapshot && inferred {
 932→			record.LegacyInferred = true
 933→		}
 934→	}
 935→	state.Snapshot = state.Store
 936→}
