 944→func scoreRecord(record MemoryRecord, promptTokens map[string]struct{}, now time.Time) (int, string) {
 945→	recordTokens := tokenize(strings.Join([]string{
 946→		record.Title,
 947→		record.Body,
 948→		record.Why,
 949→		strings.Join(record.Evidence, " "),
 950→	}, " "))
 951→	if len(recordTokens) == 0 {
 952→		return 0, ""
 953→	}
 954→
 955→	overlap := 0
 956→	for token := range promptTokens {
 957→		if _, ok := recordTokens[token]; ok {
 958→			overlap++
 959→		}
 960→	}
 961→	if overlap == 0 {
 962→		return 0, ""
 963→	}
 964→
 965→	score := overlap * 10
 966→	switch record.Kind {
 967→	case KindRepoRule, KindAgentInstruction:
 968→		score += 15
 969→	case KindSkillPatch:
 970→		score += 4
 971→	case KindWorkflowRule, KindAntiPattern, "":
 972→	}
 973→	score += minInt(record.Strength, 5)
 974→
 975→	if !record.UpdatedAt.IsZero() && now.After(record.UpdatedAt) {
 976→		age := now.Sub(record.UpdatedAt)
 977→		if age <= 14*24*time.Hour {
 978→			score += 2
 979→		}
 980→	}
 981→
 982→	return score, "keyword overlap"
 983→}
 984→
 985→func tokenize(text string) map[string]struct{} {
 986→	fields := strings.FieldsFunc(strings.ToLower(text), func(r rune) bool {
 987→		return !unicode.IsLetter(r) && !unicode.IsNumber(r)
 988→	})
 989→	tokens := make(map[string]struct{}, len(fields))
 990→	for _, field := range fields {
 991→		if len(field) < 3 {
 992→			continue
 993→		}
 994→		if _, ok := stopWords[field]; ok {
 995→			continue
 996→		}
 997→		tokens[field] = struct{}{}
 998→	}
 999→	return tokens
1000→}
