1009→func fingerprintForRecord(kind Kind, title, body string) string {
1010→	base := strings.ToLower(strings.TrimSpace(strings.Join([]string{
1011→		string(kind),
1012→		strings.TrimSpace(title),
1013→		strings.TrimSpace(body),
1014→	}, "|")))
1015→	if base == "" {
1016→		return "memory"
1017→	}
1018→	var b strings.Builder
1019→	lastDash := false
1020→	for _, r := range base {
1021→		switch {
1022→		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
1023→			b.WriteRune(r)
1024→			lastDash = false
1025→		default:
1026→			if !lastDash {
1027→				b.WriteByte('-')
1028→				lastDash = true
1029→			}
1030→		}
1031→	}
1032→	out := strings.Trim(b.String(), "-")
1033→	if out == "" {
1034→		return "memory"
1035→	}
1036→	return out
1037→}
