 892→func frequentMemoryTitles(snapshot *memoryloop.Snapshot, logs []memoryloop.InjectionLog) []string {
 893→	if snapshot == nil {
 894→		return nil
 895→	}
 896→	titleByID := make(map[string]string, len(snapshot.Records))
 897→	for _, record := range snapshot.Records {
 898→		titleByID[record.ID] = record.Title
 899→	}
 900→	counts := make(map[string]int)
 901→	for _, log := range logs {
 902→		for _, id := range log.InjectedMemoryIDs {
 903→			counts[id]++
 904→		}
 905→	}
 906→
 907→	type pair struct {
 908→		title string
 909→		count int
 910→	}
 911→	pairs := make([]pair, 0, len(counts))
 912→	for id, count := range counts {
 913→		pairs = append(pairs, pair{title: titleByID[id], count: count})
 914→	}
 915→	sort.Slice(pairs, func(i, j int) bool {
 916→		if pairs[i].count != pairs[j].count {
 917→			return pairs[i].count > pairs[j].count
 918→		}
 919→		return pairs[i].title < pairs[j].title
 920→	})
 921→
 922→	out := make([]string, 0, len(pairs))
 923→	for _, item := range pairs {
 924→		if item.title == "" {
 925→			continue
 926→		}
 927→		out = append(out, fmt.Sprintf("%s (%d)", item.title, item.count))
 928→	}
 929→	return out
 930→}
