 958→func resolveMemoryLoopScope(ctx context.Context, scopeArg, branchArg string) (memoryLoopScope, error) {
 959→	scope := memoryLoopScope{Mode: memoryLoopScopeMode(strings.ToLower(strings.TrimSpace(scopeArg)))}
 960→	if scope.Mode == "" {
 961→		scope.Mode = memoryLoopScopeRepo
 962→	}
 963→
 964→	switch scope.Mode {
 965→	case memoryLoopScopeRepo:
 966→		return scope, nil
 967→	case memoryLoopScopeBranch:
 968→		if branch := strings.TrimSpace(branchArg); branch != "" {
 969→			scope.Branch = branch
 970→			return scope, nil
 971→		}
 972→		repo, err := openRepository(ctx)
 973→		if err != nil {
 974→			return memoryLoopScope{}, fmt.Errorf("open git repository: %w", err)
 975→		}
 976→		branch := strategy.GetCurrentBranchName(repo)
 977→		if branch == "" {
 978→			return memoryLoopScope{}, errors.New("current HEAD is detached; pass --branch when using --scope branch")
 979→		}
 980→		scope.Branch = branch
 981→		return scope, nil
 982→	case memoryLoopScopeMe:
 983→		repo, err := openRepository(ctx)
 984→		if err != nil {
 985→			return memoryLoopScope{}, fmt.Errorf("open git repository: %w", err)
 986→		}
 987→		_, email := checkpoint.GetGitAuthorFromRepo(repo)
 988→		if email == "" {
 989→			return memoryLoopScope{}, errors.New("could not determine git user.email for --scope me")
 990→		}
 991→		scope.OwnerEmail = email
 992→		return scope, nil
 993→	default:
 994→		return memoryLoopScope{}, fmt.Errorf("invalid scope %q: must be repo, branch, or me", scopeArg)
 995→	}
 996→}
