 998→func queryMemoryLoopRows(ctx context.Context, idb *insightsdb.InsightsDB, scope memoryLoopScope, last int) ([]insightsdb.SessionRow, error) {
 999→	switch scope.Mode {
1000→	case memoryLoopScopeRepo:
1001→		rows, err := idb.QueryLastNSessions(ctx, last)
1002→		if err != nil {
1003→			return nil, fmt.Errorf("query repo-scoped sessions: %w", err)
1004→		}
1005→		return rows, nil
1006→	case memoryLoopScopeBranch:
1007→		rows, err := idb.QueryByBranch(ctx, scope.Branch, last)
1008→		if err != nil {
1009→			return nil, fmt.Errorf("query branch-scoped sessions: %w", err)
1010→		}
1011→		return rows, nil
1012→	case memoryLoopScopeMe:
1013→		rows, err := idb.QueryByOwnerEmail(ctx, scope.OwnerEmail, last)
1014→		if err != nil {
1015→			return nil, fmt.Errorf("query owner-scoped sessions: %w", err)
1016→		}
1017→		return rows, nil
1018→	default:
1019→		return nil, fmt.Errorf("unsupported scope mode %q", scope.Mode)
1020→	}
1021→}
