package memorylooptui

import (
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

// stateLoadedMsg is sent when the memoryloop state is loaded from disk.
type stateLoadedMsg struct {
	state *memoryloop.State
	err   error
}

// lifecycleActionMsg requests a lifecycle transition on a memory record.
type lifecycleActionMsg struct {
	id     string
	action memoryloop.LifecycleAction
}

// addMemoryMsg requests adding a new manual memory record.
type addMemoryMsg struct {
	input memoryloop.ManualRecordInput
}

// pruneMsg requests pruning stale/ineffective records.
type pruneMsg struct{}

// settingsChangedMsg indicates mode, policy, or max_injected was changed.
type settingsChangedMsg struct {
	mode             *memoryloop.Mode
	activationPolicy *memoryloop.ActivationPolicy
	maxInjected      *int
}

// testPromptMsg requests a prompt relevance test.
type testPromptMsg struct {
	prompt string
}

// testPromptResultMsg contains the results of a prompt test.
type testPromptResultMsg struct {
	matches []memoryloop.Match
}

// refreshStartedMsg indicates a refresh has begun.
type refreshStartedMsg struct{}

// refreshProgressMsg reports refresh progress text.
type refreshProgressMsg struct {
	text string
}

// refreshDoneMsg indicates a refresh has completed.
type refreshDoneMsg struct {
	state *memoryloop.State
	err   error
}

// errorFlashMsg shows a temporary error message in the status bar.
type errorFlashMsg struct {
	text string
}

// clearErrorMsg clears the error flash after a timeout.
type clearErrorMsg struct{}

package memorylooptui

import (
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

var tabNames = [4]string{"Memories", "Injection", "History", "Settings"}

func renderTabBar(s tuiStyles, activeTab int, width int, mode memoryloop.Mode, policy memoryloop.ActivationPolicy) string {
	var b strings.Builder

	for i, name := range tabNames {
		label := fmt.Sprintf("%d %s", i+1, name)
		if i == activeTab {
			b.WriteString(s.render(s.tabActive, label))
		} else {
			b.WriteString(s.render(s.tabInactive, label))
		}
		if i < len(tabNames)-1 {
			b.WriteString("  ")
		}
	}

	// Right-align mode and policy indicators
	left := b.String()
	modeStr := s.render(s.active, fmt.Sprintf("● %s", mode))
	policyStr := s.render(s.dim, fmt.Sprintf("· %s", policy))
	right := modeStr + " " + policyStr

	// Pad between left and right
	leftLen := lipglossWidth(left)
	rightLen := lipglossWidth(right)
	padding := width - leftLen - rightLen
	if padding < 1 {
		padding = 1
	}

	return left + strings.Repeat(" ", padding) + right
}

func renderStatusBar(s tuiStyles, hints string, info string, width int) string {
	hintsLen := len(hints)
	infoLen := len(info)
	padding := width - hintsLen - infoLen
	if padding < 1 {
		padding = 1
	}
	return s.render(s.statusBar, hints) + strings.Repeat(" ", padding) + s.render(s.dim, info)
}

func renderStrengthBar(strength int) string {
	if strength < 0 {
		strength = 0
	}
	if strength > 5 {
		strength = 5
	}
	filled := strings.Repeat("\u2588", strength)
	empty := strings.Repeat("\u2591", 5-strength)
	return filled + empty
}

func statusDot(s tuiStyles, status memoryloop.Status) string {
	switch status {
	case memoryloop.StatusActive:
		return s.render(s.active, "\u25cf")
	case memoryloop.StatusCandidate:
		return s.render(s.candidate, "\u25cb")
	case memoryloop.StatusSuppressed:
		return s.render(s.suppressed, "\u2715")
	case memoryloop.StatusArchived:
		return s.render(s.archived, "\u25cc")
	default:
		return " "
	}
}

func kindStyle(s tuiStyles, kind memoryloop.Kind) func(string) string {
	switch kind {
	case memoryloop.KindRepoRule, memoryloop.KindWorkflowRule:
		return func(t string) string { return s.render(s.repoRule, t) }
	case memoryloop.KindAgentInstruction:
		return func(t string) string { return s.render(s.agentInstruction, t) }
	case memoryloop.KindSkillPatch:
		return func(t string) string { return s.render(s.skillPatch, t) }
	case memoryloop.KindAntiPattern:
		return func(t string) string { return s.render(s.antiPattern, t) }
	default:
		return func(t string) string { return t }
	}
}

func timeAgo(t time.Time) string {
	if t.IsZero() {
		return "never"
	}
	d := time.Since(t)
	switch {
	case d < time.Minute:
		return "just now"
	case d < time.Hour:
		return fmt.Sprintf("%dm ago", int(d.Minutes()))
	case d < 24*time.Hour:
		return fmt.Sprintf("%dh ago", int(d.Hours()))
	default:
		return fmt.Sprintf("%dd ago", int(d.Hours()/24))
	}
}

// lipglossWidth estimates visible width by stripping ANSI sequences.
// For simple use; not a full ANSI parser.
func lipglossWidth(s string) int {
	inEscape := false
	w := 0
	for _, r := range s {
		if r == '\x1b' {
			inEscape = true
			continue
		}
		if inEscape {
			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') {
				inEscape = false
			}
			continue
		}
		w++
	}
	return w
}

package memorylooptui

import (
	"context"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
	"github.com/entireio/cli/cmd/entire/cli/termstyle"
)

const (
	tabMemories  = 0
	tabInjection = 1
	tabHistory   = 2
	tabSettings  = 3
	maxWidth     = 80
)

type rootModel struct {
	ctx          context.Context
	activeTab    int
	state        *memoryloop.State
	styles       tuiStyles
	width        int
	height       int
	showHelp     bool
	isRefreshing bool
	spinner      spinner.Model
	err          error
	errFlash     string

	memoriesTab  memoriesModel
	injectionTab injectionModel
	historyTab   historyModel
	settingsTab  settingsModel
}

// Run launches the TUI program.
func Run(ctx context.Context) error {
	s := spinner.New()
	s.Spinner = spinner.Dot

	m := rootModel{
		ctx:     ctx,
		styles:  newStyles(),
		width:   min(termstyle.GetTerminalWidth(os.Stdout), maxWidth),
		spinner: s,
	}

	p := tea.NewProgram(m, tea.WithAltScreen())
	_, err := p.Run()
	return err
}

func (m rootModel) Init() tea.Cmd {
	return func() tea.Msg {
		state, err := memoryloop.LoadState(m.ctx)
		return stateLoadedMsg{state: state, err: err}
	}
}

func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = min(msg.Width, maxWidth)
		m.height = msg.Height
		m.memoriesTab.setSize(m.width, m.contentHeight())
		m.injectionTab.setSize(m.width, m.contentHeight())
		m.historyTab.setSize(m.width, m.contentHeight())
		m.settingsTab.setSize(m.width, m.contentHeight())
		return m, nil

	case tea.KeyMsg:
		// Global keys -- check before delegating to tabs
		switch {
		case key.Matches(msg, globalKeyMap.Quit):
			return m, tea.Quit
		case key.Matches(msg, globalKeyMap.Help):
			m.showHelp = !m.showHelp
			return m, nil
		case key.Matches(msg, globalKeyMap.TabNext):
			m.activeTab = (m.activeTab + 1) % 4
			return m, nil
		case key.Matches(msg, globalKeyMap.TabPrev):
			m.activeTab = (m.activeTab + 3) % 4
			return m, nil
		case key.Matches(msg, globalKeyMap.Tab1):
			m.activeTab = tabMemories
			return m, nil
		case key.Matches(msg, globalKeyMap.Tab2):
			m.activeTab = tabInjection
			return m, nil
		case key.Matches(msg, globalKeyMap.Tab3):
			m.activeTab = tabHistory
			return m, nil
		case key.Matches(msg, globalKeyMap.Tab4):
			m.activeTab = tabSettings
			return m, nil
		}

	case stateLoadedMsg:
		if msg.err != nil {
			m.err = msg.err
			return m, nil
		}
		m.state = msg.state
		m.pushState()
		return m, nil

	case lifecycleActionMsg:
		return m.handleLifecycleAction(msg)

	case addMemoryMsg:
		return m.handleAddMemory(msg)

	case pruneMsg:
		return m.handlePrune()

	case settingsChangedMsg:
		return m.handleSettingsChanged(msg)

	case testPromptMsg:
		if m.state == nil || m.state.Store == nil {
			return m, nil
		}
		matches := memoryloop.SelectRelevant(*m.state.Store, msg.prompt, time.Now())
		return m, func() tea.Msg { return testPromptResultMsg{matches: matches} }

	case errorFlashMsg:
		m.errFlash = msg.text
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearErrorMsg{} })

	case clearErrorMsg:
		m.errFlash = ""
		return m, nil
	}

	// Delegate to active tab
	var cmd tea.Cmd
	switch m.activeTab {
	case tabMemories:
		m.memoriesTab, cmd = m.memoriesTab.update(msg)
	case tabInjection:
		m.injectionTab, cmd = m.injectionTab.update(msg)
	case tabHistory:
		m.historyTab, cmd = m.historyTab.update(msg)
	case tabSettings:
		m.settingsTab, cmd = m.settingsTab.update(msg)
	}
	if cmd != nil {
		cmds = append(cmds, cmd)
	}

	return m, tea.Batch(cmds...)
}

func (m rootModel) View() string {
	if m.err != nil {
		return fmt.Sprintf("Error loading memory store: %v\nCheck .entire/memory-loop.json", m.err)
	}
	if m.state == nil {
		return "Loading..."
	}

	var b strings.Builder

	// Tab bar
	mode := memoryloop.ModeOff
	policy := memoryloop.ActivationPolicyReview
	if m.state.Store != nil {
		mode = m.state.Store.Mode
		policy = m.state.Store.ActivationPolicy
	}
	b.WriteString(renderTabBar(m.styles, m.activeTab, m.width, mode, policy))
	b.WriteString("\n")

	// Content area
	if m.showHelp {
		b.WriteString(m.renderHelp())
	} else {
		switch m.activeTab {
		case tabMemories:
			b.WriteString(m.memoriesTab.view())
		case tabInjection:
			b.WriteString(m.injectionTab.view())
		case tabHistory:
			b.WriteString(m.historyTab.view())
		case tabSettings:
			b.WriteString(m.settingsTab.view())
		}
	}

	// Status bar
	b.WriteString("\n")
	if m.errFlash != "" {
		b.WriteString(m.styles.render(m.styles.errorFlash, m.errFlash))
	} else {
		hints := m.activeTabHints()
		info := m.activeTabInfo()
		b.WriteString(renderStatusBar(m.styles, hints, info, m.width))
	}

	return b.String()
}

func (m rootModel) contentHeight() int {
	// Total height minus tab bar (1) and status bar (1) and newlines (2)
	h := m.height - 4
	if h < 5 {
		h = 5
	}
	return h
}

func (m *rootModel) pushState() {
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
}

func (m rootModel) saveState() error {
	return memoryloop.SaveState(m.ctx, m.state)
}

func (m rootModel) handleLifecycleAction(msg lifecycleActionMsg) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}
	updated, _, err := memoryloop.TransitionRecordLifecycle(m.state.Store.Records, msg.id, msg.action, time.Now())
	if err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: err.Error()} }
	}
	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("save failed: %v", err)} }
	}
	m.pushState()
	return m, nil
}

func (m rootModel) handleAddMemory(msg addMemoryMsg) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}
	updated, _, err := memoryloop.AddManualRecord(m.state.Store.Records, msg.input, time.Now())
	if err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: err.Error()} }
	}
	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("save failed: %v", err)} }
	}
	m.pushState()
	return m, nil
}

func (m rootModel) handlePrune() (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}
	updated, result := memoryloop.PruneRecords(m.state.Store.Records, time.Now())
	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("save failed: %v", err)} }
	}
	m.pushState()
	msg := fmt.Sprintf("Pruned %d records", result.ArchivedCount)
	return m, func() tea.Msg { return errorFlashMsg{text: msg} }
}

func (m rootModel) handleSettingsChanged(msg settingsChangedMsg) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil {
		return m, nil
	}
	if msg.mode != nil {
		m.state.Store.Mode = *msg.mode
	}
	if msg.activationPolicy != nil {
		m.state.Store.ActivationPolicy = *msg.activationPolicy
	}
	if msg.maxInjected != nil {
		m.state.Store.MaxInjected = *msg.maxInjected
	}
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("save failed: %v", err)} }
	}
	m.pushState()
	return m, nil
}

func (m rootModel) activeTabHints() string {
	switch m.activeTab {
	case tabMemories:
		return "j/k navigate · enter expand · f filter · a activate · s suppress · x archive · n new · ? help"
	case tabInjection:
		return "i focus input · enter test · esc unfocus · j/k navigate · ? help"
	case tabHistory:
		return "j/k navigate · R refresh · ? help"
	case tabSettings:
		return "m mode · p policy · +/- max injected · ? help"
	default:
		return "? help · q quit"
	}
}

func (m rootModel) activeTabInfo() string {
	if m.state == nil || m.state.Store == nil {
		return ""
	}
	switch m.activeTab {
	case tabMemories:
		return fmt.Sprintf("%d records", len(m.state.Store.Records))
	case tabInjection:
		return fmt.Sprintf("%d logs", len(m.state.InjectionLogs))
	case tabHistory:
		return fmt.Sprintf("%d refreshes", len(m.state.Store.RefreshHistory))
	default:
		return ""
	}
}

func (m rootModel) renderHelp() string {
	var b strings.Builder
	b.WriteString(m.styles.render(m.styles.bold, "Keyboard Shortcuts"))
	b.WriteString("\n\n")

	b.WriteString(m.styles.render(m.styles.title, "Global"))
	b.WriteString("\n")
	b.WriteString("  Tab/Shift+Tab  cycle tabs    1-4  jump to tab\n")
	b.WriteString("  q              quit          ?    toggle help\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Memories"))
	b.WriteString("\n")
	b.WriteString("  j/k  navigate    enter  toggle detail    f  filter    /  search\n")
	b.WriteString("  a    activate    P      promote          s  suppress  u  unsuppress\n")
	b.WriteString("  x    archive     D      prune            n  new memory\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Injection"))
	b.WriteString("\n")
	b.WriteString("  i  focus input    enter  test prompt    esc  unfocus    j/k  navigate\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "History"))
	b.WriteString("\n")
	b.WriteString("  j/k  navigate    R  trigger refresh\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Settings"))
	b.WriteString("\n")
	b.WriteString("  m  cycle mode    p  cycle policy    +/-  max injected\n")

	return b.String()
}

