 41→func newMemoriesModel(s tuiStyles) memoriesModel {
 42→	columns := []table.Column{
 43→		{Title: " ", Width: 2},
 44→		{Title: "Title", Width: 30},
 45→		{Title: "Kind", Width: 14},
 46→		{Title: "Scope", Width: 5},
