 53→		table.WithFocused(true),
 54→	)
 55→	st := table.DefaultStyles()
 56→	st.Header = st.Header.
 57→		BorderStyle(lipgloss.NormalBorder()).
 58→		BorderBottom(true).
 59→		Bold(false).
 60→		Faint(true)
 61→	st.Selected = st.Selected.
 62→		Foreground(lipgloss.Color("6")).
 63→		Bold(false)
 64→	t.SetStyles(st)
