 77→func (m *memoriesModel) setSize(w, h int) {
 78→	m.width = w
 79→	m.height = h
 80→	// Reserve 3 lines for filter bar + detail pane header area
 81→	tableH := h - 3
 82→	if m.showDetail {
 83→		tableH = h / 2
 84→	}
 85→	if tableH < 3 {
 86→		tableH = 3
 87→	}
 88→	m.table.SetWidth(w)
 89→	m.table.SetHeight(tableH)
 90→}
 91→
 92→func (m *memoriesModel) rebuildTable() {
 93→	if m.state == nil || m.state.Store == nil {
 94→		m.records = nil
 95→		m.table.SetRows(nil)
 96→		return
 97→	}
 98→
 99→	var filtered []memoryloop.MemoryRecord
100→	for _, r := range m.state.Store.Records {
101→		if !m.matchesFilter(r) {
102→			continue
103→		}
104→		if m.searchMode && m.searchText != "" {
105→			if !strings.Contains(strings.ToLower(r.Title), strings.ToLower(m.searchText)) {
106→				continue
107→			}
108→		}
109→		filtered = append(filtered, r)
110→	}
111→	m.records = filtered
112→
113→	rows := make([]table.Row, len(filtered))
114→	for i, r := range filtered {
115→		rows[i] = table.Row{
116→			statusDotPlain(r.Status),
117→			truncate(r.Title, 30),
118→			string(r.Kind),
119→			string(r.ScopeKind),
120→			renderStrengthBar(r.Strength),
121→			string(r.Outcome),
122→			strconv.Itoa(r.InjectCount),
123→		}
124→	}
125→	m.table.SetRows(rows)
126→}
