128→func (m memoriesModel) matchesFilter(r memoryloop.MemoryRecord) bool {
129→	switch m.filter {
130→	case filterAll:
131→		return true
132→	case filterActive:
133→		return r.Status == memoryloop.StatusActive
134→	case filterCandidate:
135→		return r.Status == memoryloop.StatusCandidate
136→	case filterSuppressed:
137→		return r.Status == memoryloop.StatusSuppressed
138→	case filterArchived:
139→		return r.Status == memoryloop.StatusArchived
140→	default:
141→		return true
142→	}
143→}
