145→func (m memoriesModel) selectedRecord() *memoryloop.MemoryRecord {
146→	cursor := m.table.Cursor()
147→	if cursor < 0 || cursor >= len(m.records) {
148→		return nil
149→	}
150→	return &m.records[cursor]
