153→func (m memoriesModel) update(msg tea.Msg) (memoriesModel, tea.Cmd) {
154→	if keyMsg, ok := msg.(tea.KeyMsg); ok {
155→		if m.searchMode {
156→			return m.updateSearch(keyMsg)
