221→func (m memoriesModel) updateSearch(msg tea.KeyMsg) (memoriesModel, tea.Cmd) {
222→	switch msg.String() {
223→	case "esc":
224→		m.searchMode = false
225→		m.searchText = ""
226→		m.rebuildTable()
227→		return m, nil
228→	case "enter":
229→		m.searchMode = false
230→		return m, nil
231→	case "backspace":
232→		if len(m.searchText) > 0 {
233→			m.searchText = m.searchText[:len(m.searchText)-1]
234→			m.rebuildTable()
235→		}
236→		return m, nil
237→	default:
238→		if len(msg.String()) == 1 {
239→			m.searchText += msg.String()
240→			m.rebuildTable()
241→		}
242→		return m, nil
243→	}
244→}
