246→func (m memoriesModel) view() string {
247→	if m.state == nil || m.state.Store == nil || len(m.state.Store.Records) == 0 {
248→		return "\n  No memory store found. Switch to History tab and press R to refresh.\n"
249→	}
250→
251→	var b strings.Builder
252→
253→	// Filter bar
254→	b.WriteString(m.renderFilterBar())
255→	b.WriteString("\n")
256→
257→	// Search bar (if active)
258→	if m.searchMode {
259→		fmt.Fprintf(&b, "  / %s\u2588\n", m.searchText)
260→	}
261→
262→	// Table
263→	b.WriteString(m.table.View())
264→
265→	// Detail pane
266→	if m.showDetail {
267→		b.WriteString("\n")
268→		b.WriteString(m.renderDetail())
269→	}
270→
271→	return b.String()
272→}
