274→func (m memoriesModel) renderFilterBar() string {
275→	counts := m.statusCounts()
276→	var parts []string
277→	for i, label := range filterLabels {
278→		count := counts[i]
279→		text := fmt.Sprintf("%s (%d)", label, count)
280→		if statusFilter(i) == m.filter {
281→			parts = append(parts, m.styles.render(m.styles.title, text))
282→		} else {
283→			parts = append(parts, m.styles.render(m.styles.dim, text))
284→		}
285→	}
286→	return "  " + strings.Join(parts, "  ")
287→}
288→
289→func (m memoriesModel) statusCounts() [5]int {
290→	var counts [5]int
291→	if m.state == nil || m.state.Store == nil {
292→		return counts
293→	}
294→	for _, r := range m.state.Store.Records {
295→		counts[0]++ // all
296→		switch r.Status {
297→		case memoryloop.StatusActive:
298→			counts[1]++
299→		case memoryloop.StatusCandidate:
300→			counts[2]++
301→		case memoryloop.StatusSuppressed:
302→			counts[3]++
303→		case memoryloop.StatusArchived:
304→			counts[4]++
305→		}
306→	}
307→	return counts
308→}
309→
310→func (m memoriesModel) renderDetail() string {
311→	r := m.selectedRecord()
312→	if r == nil {
313→		return ""
314→	}
315→	var b strings.Builder
316→	// Title line
317→	b.WriteString("  ")
318→	b.WriteString(m.styles.render(m.styles.title, r.Title))
319→	b.WriteString("  ")
320→	b.WriteString(kindStyle(m.styles, r.Kind)(string(r.Kind)))
321→	b.WriteString("  ")
322→	b.WriteString(statusDot(m.styles, r.Status))
323→	b.WriteString(" ")
324→	b.WriteString(string(r.Status))
325→	b.WriteString("  ")
326→	b.WriteString(m.styles.render(m.styles.dim, string(r.ScopeKind)))
327→	b.WriteString("  ")
328→	b.WriteString(m.styles.render(m.styles.dim, string(r.Origin)))
329→	b.WriteString("\n")
330→
331→	// Body
332→	if r.Body != "" {
333→		b.WriteString("  " + r.Body + "\n")
334→	}
335→
336→	// Why
337→	if r.Why != "" {
338→		b.WriteString("  ")
339→		b.WriteString(m.styles.render(m.styles.dim, "WHY"))
340→		b.WriteString("\n")
341→		b.WriteString("  " + r.Why + "\n")
342→	}
343→
344→	// Stats
345→	b.WriteString("  ")
346→	stats := fmt.Sprintf("strength: %d/5 · injected: %dx · matched: %dx · last injected: %s · created: %s",
347→		r.Strength, r.InjectCount, r.MatchCount, timeAgo(r.LastInjectedAt), timeAgo(r.CreatedAt))
348→	b.WriteString(m.styles.render(m.styles.dim, stats))
349→	b.WriteString("\n")
350→
351→	return b.String()
352→}
