358→	case memoryloop.StatusCandidate:
359→		return "\u25cb"
360→	case memoryloop.StatusSuppressed:
361→		return "\u2715"
362→	case memoryloop.StatusArchived:
363→		return "\u25cc"
364→	default:
365→		return " "
366→	}
367→}
