  1→package memorylooptui
  2→
  3→import (
  4→	"fmt"
  5→	"strings"
  6→	"time"
  7→
  8→	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
  9→)
 10→
 11→var tabNames = [4]string{"Memories", "Injection", "History", "Settings"}
 12→
 13→func renderTabBar(s tuiStyles, activeTab int, width int, mode memoryloop.Mode, policy memoryloop.ActivationPolicy) string {
 14→	var b strings.Builder
 15→
 16→	for i, name := range tabNames {
 17→		label := fmt.Sprintf("%d %s", i+1, name)
 18→		if i == activeTab {
 19→			b.WriteString(s.render(s.tabActive, label))
 20→		} else {
 21→			b.WriteString(s.render(s.tabInactive, label))
 22→		}
 23→		if i < len(tabNames)-1 {
 24→			b.WriteString("  ")
 25→		}
 26→	}
 27→
 28→	// Right-align mode and policy indicators
 29→	left := b.String()
 30→	modeStr := s.render(s.active, fmt.Sprintf("● %s", mode))
 31→	policyStr := s.render(s.dim, fmt.Sprintf("· %s", policy))
 32→	right := modeStr + " " + policyStr
 33→
 34→	// Pad between left and right
 35→	leftLen := lipglossWidth(left)
 36→	rightLen := lipglossWidth(right)
 37→	padding := width - leftLen - rightLen
 38→	if padding < 1 {
 39→		padding = 1
 40→	}
 41→
 42→	return left + strings.Repeat(" ", padding) + right
 43→}
 44→
 45→func renderStatusBar(s tuiStyles, hints string, info string, width int) string {
 46→	hintsLen := len(hints)
 47→	infoLen := len(info)
 48→	padding := width - hintsLen - infoLen
 49→	if padding < 1 {
 50→		padding = 1
 51→	}
 52→	return s.render(s.statusBar, hints) + strings.Repeat(" ", padding) + s.render(s.dim, info)
 53→}
 54→
 55→func renderStrengthBar(strength int) string {
 56→	if strength < 0 {
 57→		strength = 0
 58→	}
 59→	if strength > 5 {
 60→		strength = 5
 61→	}
 62→	filled := strings.Repeat("\u2588", strength)
 63→	empty := strings.Repeat("\u2591", 5-strength)
 64→	return filled + empty
 65→}
 66→
 67→func statusDot(s tuiStyles, status memoryloop.Status) string {
 68→	switch status {
 69→	case memoryloop.StatusActive:
 70→		return s.render(s.active, "\u25cf")
 71→	case memoryloop.StatusCandidate:
 72→		return s.render(s.candidate, "\u25cb")
 73→	case memoryloop.StatusSuppressed:
 74→		return s.render(s.suppressed, "\u2715")
 75→	case memoryloop.StatusArchived:
 76→		return s.render(s.archived, "\u25cc")
 77→	default:
 78→		return " "
 79→	}
 80→}
 81→
 82→func kindStyle(s tuiStyles, kind memoryloop.Kind) func(string) string {
 83→	switch kind {
 84→	case memoryloop.KindRepoRule, memoryloop.KindWorkflowRule:
 85→		return func(t string) string { return s.render(s.repoRule, t) }
 86→	case memoryloop.KindAgentInstruction:
 87→		return func(t string) string { return s.render(s.agentInstruction, t) }
 88→	case memoryloop.KindSkillPatch:
 89→		return func(t string) string { return s.render(s.skillPatch, t) }
 90→	case memoryloop.KindAntiPattern:
 91→		return func(t string) string { return s.render(s.antiPattern, t) }
 92→	default:
 93→		return func(t string) string { return t }
 94→	}
