package memorylooptui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

//nolint:recvcheck // bubbletea pattern: pointer receivers for mutation, value for update/view
type injectionModel struct {
	state      *memoryloop.State
	styles     tuiStyles
	width      int
	height     int
	logTable   table.Model
	input      textinput.Model
	inputFocus bool
	matches    []memoryloop.Match
}

func newInjectionModel(s tuiStyles) injectionModel {
	columns := []table.Column{
		{Title: "Time", Width: 10},
		{Title: "Session", Width: 10},
		{Title: "Count", Width: 5},
		{Title: "Prompt Preview", Width: 40},
	}
	t := table.New(
		table.WithColumns(columns),
		table.WithFocused(true),
	)
	st := table.DefaultStyles()
	st.Header = st.Header.
		BorderStyle(lipgloss.NormalBorder()).
		BorderBottom(true).
		Bold(false).
		Faint(true)
	st.Selected = st.Selected.
		Foreground(lipgloss.Color("6")).
		Bold(false)
	t.SetStyles(st)

	ti := textinput.New()
	ti.Placeholder = "type a prompt to test memory matching..."
	ti.Prompt = "> "
	ti.Width = 60

	return injectionModel{
		styles:   s,
		logTable: t,
		input:    ti,
	}
}

func (m *injectionModel) setState(state *memoryloop.State) {
	m.state = state
	m.rebuildLogTable()
}

func (m *injectionModel) setSize(w, h int) {
	m.width = w
	m.height = h
	tableH := h - 10 // Reserve space for input + matches
	if tableH < 3 {
		tableH = 3
	}
	m.logTable.SetWidth(w)
	m.logTable.SetHeight(tableH)
	m.input.Width = w - 6
}

func (m *injectionModel) rebuildLogTable() {
	if m.state == nil {
		m.logTable.SetRows(nil)
		return
	}
	logs := m.state.InjectionLogs
	rows := make([]table.Row, len(logs))
	for i, l := range logs {
		rows[i] = table.Row{
			timeAgo(l.InjectedAt),
			truncate(l.SessionID, 10),
			fmt.Sprintf("%d", len(l.InjectedMemoryIDs)),
			truncate(l.PromptPreview, 40),
		}
	}
	m.logTable.SetRows(rows)
}

func (m injectionModel) update(msg tea.Msg) (injectionModel, tea.Cmd) {
	switch msg := msg.(type) {
	case testPromptResultMsg:
		m.matches = msg.matches
		return m, nil

	case tea.KeyMsg:
		if m.inputFocus {
			switch {
			case key.Matches(msg, injectionKeyMap.Escape):
				m.inputFocus = false
				m.input.Blur()
				return m, nil
			case key.Matches(msg, injectionKeyMap.Enter):
				prompt := m.input.Value()
				if prompt != "" {
					return m, func() tea.Msg { return testPromptMsg{prompt: prompt} }
				}
				return m, nil
			}
			// Delegate to text input
			var cmd tea.Cmd
			m.input, cmd = m.input.Update(msg)
			return m, cmd
		}

		if key.Matches(msg, injectionKeyMap.Focus) {
			m.inputFocus = true
			m.input.Focus()
			return m, textinput.Blink
		}
	}

	if !m.inputFocus {
		var cmd tea.Cmd
		m.logTable, cmd = m.logTable.Update(msg)
		return m, cmd
	}
	return m, nil
}

func (m injectionModel) view() string {
	var b strings.Builder

	// Prompt tester section
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, "PROMPT TESTER"))
	b.WriteString("\n")
	b.WriteString("  ")
	b.WriteString(m.input.View())
	b.WriteString("\n")

	// Match results
	if len(m.matches) > 0 {
		b.WriteString("\n  ")
		b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf("MATCHES (%d)", len(m.matches))))
		b.WriteString("\n")
		for _, match := range m.matches {
			b.WriteString(fmt.Sprintf("  %s  %s\n",
				m.styles.render(m.styles.title, match.Record.Title),
				m.styles.render(m.styles.active, fmt.Sprintf("score: %d", match.Score)),
			))
			if match.Reason != "" {
				b.WriteString(fmt.Sprintf("    %s\n", m.styles.render(m.styles.dim, match.Reason)))
			}
		}
	}

	// Injection logs
	b.WriteString("\n  ")
	b.WriteString(m.styles.render(m.styles.dim, "RECENT INJECTIONS"))
	b.WriteString("\n")

	if m.state == nil || len(m.state.InjectionLogs) == 0 {
		b.WriteString("  No injection logs yet. Memories inject when mode is auto.\n")
	} else {
		b.WriteString(m.logTable.View())
	}

	return b.String()
}

package memorylooptui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/table"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

//nolint:recvcheck // bubbletea pattern: pointer receivers for mutation, value for update/view
type historyModel struct {
	state  *memoryloop.State
	styles tuiStyles
	width  int
	height int
	table  table.Model
}

func newHistoryModel(s tuiStyles) historyModel {
	columns := []table.Column{
		{Title: "Time", Width: 12},
		{Title: "Scope", Width: 8},
		{Title: "Generated", Width: 9},
		{Title: "Activated", Width: 9},
		{Title: "Candidate", Width: 9},
		{Title: "Window", Width: 7},
	}
	t := table.New(
		table.WithColumns(columns),
		table.WithFocused(true),
	)
	st := table.DefaultStyles()
	st.Header = st.Header.
		BorderStyle(lipgloss.NormalBorder()).
		BorderBottom(true).
		Bold(false).
		Faint(true)
	st.Selected = st.Selected.
		Foreground(lipgloss.Color("6")).
		Bold(false)
	t.SetStyles(st)

	return historyModel{
		styles: s,
		table:  t,
	}
}

func (m *historyModel) setState(state *memoryloop.State) {
	m.state = state
	m.rebuildTable()
}

func (m *historyModel) setSize(w, h int) {
	m.width = w
	m.height = h
	m.table.SetWidth(w)
	m.table.SetHeight(h - 2)
}

func (m *historyModel) rebuildTable() {
	if m.state == nil || m.state.Store == nil {
		m.table.SetRows(nil)
		return
	}
	history := m.state.Store.RefreshHistory
	rows := make([]table.Row, len(history))
	for i, h := range history {
		scope := h.Scope
		if h.ScopeValue != "" {
			scope += ":" + truncate(h.ScopeValue, 6)
		}
		rows[i] = table.Row{
			timeAgo(h.At),
			scope,
			fmt.Sprintf("+%d", h.GeneratedCount),
			fmt.Sprintf("%d", h.ActivatedCount),
			fmt.Sprintf("%d", h.CandidateCount),
			fmt.Sprintf("%d", h.SourceWindow),
		}
	}
	m.table.SetRows(rows)
}

func (m historyModel) update(msg tea.Msg) (historyModel, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		if key.Matches(msg, historyKeyMap.Refresh) {
			// Refresh is an async operation handled by root model.
			// For now, emit refreshStartedMsg so root can orchestrate.
			return m, func() tea.Msg { return refreshStartedMsg{} }
		}
	}

	var cmd tea.Cmd
	m.table, cmd = m.table.Update(msg)
	return m, cmd
}

func (m historyModel) view() string {
	if m.state == nil || m.state.Store == nil || len(m.state.Store.RefreshHistory) == 0 {
		var b strings.Builder
		b.WriteString("\n  No refresh history yet.\n")
		b.WriteString("  Press R to run your first refresh.\n")
		return b.String()
	}

	return m.table.View()
}

package memorylooptui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/key"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

var modeOrder = []memoryloop.Mode{memoryloop.ModeOff, memoryloop.ModeManual, memoryloop.ModeAuto}
var policyOrder = []memoryloop.ActivationPolicy{memoryloop.ActivationPolicyReview, memoryloop.ActivationPolicyAuto}

//nolint:recvcheck // bubbletea pattern: pointer receivers for mutation, value for update/view
type settingsModel struct {
	state  *memoryloop.State
	styles tuiStyles
	width  int
	height int
}

func (m *settingsModel) setState(state *memoryloop.State) { m.state = state }
func (m *settingsModel) setSize(w, h int)                 { m.width = w; m.height = h }

func (m settingsModel) update(msg tea.Msg) (settingsModel, tea.Cmd) {
	if m.state == nil || m.state.Store == nil {
		return m, nil
	}

	switch msg := msg.(type) {
	case tea.KeyMsg:
		switch {
		case key.Matches(msg, settingsKeyMap.Mode):
			next := cycleMode(m.state.Store.Mode)
			return m, func() tea.Msg { return settingsChangedMsg{mode: &next} }

		case key.Matches(msg, settingsKeyMap.Policy):
			next := cyclePolicy(m.state.Store.ActivationPolicy)
			return m, func() tea.Msg { return settingsChangedMsg{activationPolicy: &next} }

		case key.Matches(msg, settingsKeyMap.MaxUp):
			next := m.state.Store.MaxInjected + 1
			if next > 10 {
				next = 10
			}
			return m, func() tea.Msg { return settingsChangedMsg{maxInjected: &next} }

		case key.Matches(msg, settingsKeyMap.MaxDown):
			next := m.state.Store.MaxInjected - 1
			if next < 1 {
				next = 1
			}
			return m, func() tea.Msg { return settingsChangedMsg{maxInjected: &next} }
		}
	}
	return m, nil
}

func (m settingsModel) view() string {
	if m.state == nil || m.state.Store == nil {
		return "\n  No settings available.\n"
	}
	store := m.state.Store

	var b strings.Builder
	b.WriteString("\n")

	// Mode
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.bold, "Mode"))
	b.WriteString("\n")
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, "Controls whether active memories inject into prompts"))
	b.WriteString("\n  ")
	for _, mode := range modeOrder {
		label := string(mode)
		if mode == store.Mode {
			b.WriteString(m.styles.render(m.styles.active, fmt.Sprintf("[%s]", label)))
		} else {
			b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf(" %s ", label)))
		}
		b.WriteString("  ")
	}
	b.WriteString("\n\n")

	// Policy
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.bold, "Activation Policy"))
	b.WriteString("\n")
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, "What happens to newly generated memories"))
	b.WriteString("\n  ")
	for _, pol := range policyOrder {
		label := string(pol)
		if pol == store.ActivationPolicy {
			b.WriteString(m.styles.render(m.styles.candidate, fmt.Sprintf("[%s]", label)))
		} else {
			b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf(" %s ", label)))
		}
		b.WriteString("  ")
	}
	b.WriteString("\n\n")

	// Max Injected
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.bold, "Max Injected"))
	b.WriteString("\n")
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, "Maximum memories per prompt injection"))
	b.WriteString("\n  ")
	b.WriteString(fmt.Sprintf("< %s >",
		m.styles.render(m.styles.title, fmt.Sprintf(" %d ", store.MaxInjected))))
	b.WriteString("\n\n")

	// Injection enabled
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.bold, "Injection"))
	b.WriteString("\n  ")
	if store.InjectionEnabled {
		b.WriteString(m.styles.render(m.styles.active, "* enabled"))
	} else {
		b.WriteString(m.styles.render(m.styles.suppressed, "o disabled"))
	}
	b.WriteString("\n\n")

	// Stats
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf("Last refresh: %s", timeAgo(store.GeneratedAt))))
	b.WriteString("\n  ")
	b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf("Store version: %d", store.Version)))
	b.WriteString("\n  ")
	b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf("Source window: %d sessions", store.SourceWindow)))
	b.WriteString("\n")

	return b.String()
}

func cycleMode(current memoryloop.Mode) memoryloop.Mode {
	for i, m := range modeOrder {
		if m == current {
			return modeOrder[(i+1)%len(modeOrder)]
		}
	}
	return memoryloop.ModeOff
}

func cyclePolicy(current memoryloop.ActivationPolicy) memoryloop.ActivationPolicy {
	for i, p := range policyOrder {
		if p == current {
			return policyOrder[(i+1)%len(policyOrder)]
		}
	}
	return memoryloop.ActivationPolicyReview
}

