114→// lipglossWidth estimates visible width by stripping ANSI sequences.
115→// For simple use; not a full ANSI parser.
116→func lipglossWidth(s string) int {
117→	inEscape := false
118→	w := 0
119→	for _, r := range s {
120→		if r == '\x1b' {
121→			inEscape = true
122→			continue
123→		}
124→		if inEscape {
125→			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') {
126→				inEscape = false
127→			}
128→			continue
129→		}
130→		w++
131→	}
132→	return w
133→}
