 12→var modeOrder = []memoryloop.Mode{memoryloop.ModeOff, memoryloop.ModeManual, memoryloop.ModeAuto}
 13→var policyOrder = []memoryloop.ActivationPolicy{memoryloop.ActivationPolicyReview, memoryloop.ActivationPolicyAuto}
 14→
 15→//nolint:recvcheck // bubbletea pattern: pointer receivers for mutation, value for update/view
 16→type settingsModel struct {
 17→	state  *memoryloop.State
 18→	styles tuiStyles
 19→	width  int
 20→	height int
 21→}
 22→
 23→func (m *settingsModel) setState(state *memoryloop.State) { m.state = state }
 24→func (m *settingsModel) setSize(w, h int)                 { m.width = w; m.height = h }
 25→
 26→func (m settingsModel) update(msg tea.Msg) (settingsModel, tea.Cmd) {
 27→	if m.state == nil || m.state.Store == nil {
 28→		return m, nil
 29→	}
 30→
 31→	if keyMsg, ok := msg.(tea.KeyMsg); ok {
 32→		switch {
 33→		case key.Matches(keyMsg, settingsKeyMap.Mode):
 34→			next := cycleMode(m.state.Store.Mode)
 35→			return m, func() tea.Msg { return settingsChangedMsg{mode: &next} }
 36→
 37→		case key.Matches(keyMsg, settingsKeyMap.Policy):
 38→			next := cyclePolicy(m.state.Store.ActivationPolicy)
 39→			return m, func() tea.Msg { return settingsChangedMsg{activationPolicy: &next} }
 40→
 41→		case key.Matches(keyMsg, settingsKeyMap.MaxUp):
 42→			next := m.state.Store.MaxInjected + 1
 43→			if next > 10 {
 44→				next = 10
 45→			}
 46→			return m, func() tea.Msg { return settingsChangedMsg{maxInjected: &next} }
 47→
 48→		case key.Matches(keyMsg, settingsKeyMap.MaxDown):
 49→			next := m.state.Store.MaxInjected - 1
 50→			if next < 1 {
 51→				next = 1
 52→			}
 53→			return m, func() tea.Msg { return settingsChangedMsg{maxInjected: &next} }
 54→		}
 55→	}
 56→	return m, nil
 57→}
 58→
 59→func (m settingsModel) view() string {
 60→	if m.state == nil || m.state.Store == nil {
 61→		return "\n  No settings available.\n"
 62→	}
 63→	store := m.state.Store
 64→
 65→	var b strings.Builder
 66→	b.WriteString("\n")
 67→
 68→	// Mode
 69→	b.WriteString("  ")
 70→	b.WriteString(m.styles.render(m.styles.bold, "Mode"))
 71→	b.WriteString("\n")
 72→	b.WriteString("  ")
 73→	b.WriteString(m.styles.render(m.styles.dim, "Controls whether active memories inject into prompts"))
 74→	b.WriteString("\n  ")
 75→	for _, mode := range modeOrder {
 76→		label := string(mode)
 77→		if mode == store.Mode {
 78→			b.WriteString(m.styles.render(m.styles.active, fmt.Sprintf("[%s]", label)))
 79→		} else {
 80→			b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf(" %s ", label)))
 81→		}
 82→		b.WriteString("  ")
 83→	}
 84→	b.WriteString("\n\n")
 85→
 86→	// Policy
 87→	b.WriteString("  ")
 88→	b.WriteString(m.styles.render(m.styles.bold, "Activation Policy"))
 89→	b.WriteString("\n")
 90→	b.WriteString("  ")
 91→	b.WriteString(m.styles.render(m.styles.dim, "What happens to newly generated memories"))
 92→	b.WriteString("\n  ")
 93→	for _, pol := range policyOrder {
 94→		label := string(pol)
 95→		if pol == store.ActivationPolicy {
 96→			b.WriteString(m.styles.render(m.styles.candidate, fmt.Sprintf("[%s]", label)))
 97→		} else {
 98→			b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf(" %s ", label)))
 99→		}
100→		b.WriteString("  ")
101→	}
102→	b.WriteString("\n\n")
103→
104→	// Max Injected
105→	b.WriteString("  ")
106→	b.WriteString(m.styles.render(m.styles.bold, "Max Injected"))
107→	b.WriteString("\n")
108→	b.WriteString("  ")
109→	b.WriteString(m.styles.render(m.styles.dim, "Maximum memories per prompt injection"))
110→	b.WriteString("\n  ")
111→	fmt.Fprintf(&b, "< %s >",
112→		m.styles.render(m.styles.title, fmt.Sprintf(" %d ", store.MaxInjected)))
113→	b.WriteString("\n\n")
114→
115→	// Injection enabled
116→	b.WriteString("  ")
117→	b.WriteString(m.styles.render(m.styles.bold, "Injection"))
118→	b.WriteString("\n  ")
119→	if store.InjectionEnabled {
120→		b.WriteString(m.styles.render(m.styles.active, "* enabled"))
121→	} else {
122→		b.WriteString(m.styles.render(m.styles.suppressed, "o disabled"))
123→	}
124→	b.WriteString("\n\n")
125→
126→	// Stats
127→	b.WriteString("  ")
128→	b.WriteString(m.styles.render(m.styles.dim, "Last refresh: "+timeAgo(store.GeneratedAt)))
129→	b.WriteString("\n  ")
130→	b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf("Store version: %d", store.Version)))
131→	b.WriteString("\n  ")
132→	b.WriteString(m.styles.render(m.styles.dim, fmt.Sprintf("Source window: %d sessions", store.SourceWindow)))
133→	b.WriteString("\n")
134→
135→	return b.String()
136→}
