138→func cycleMode(current memoryloop.Mode) memoryloop.Mode {
139→	for i, m := range modeOrder {
140→		if m == current {
141→			return modeOrder[(i+1)%len(modeOrder)]
142→		}
143→	}
144→	return memoryloop.ModeOff
145→}
146→
147→func cyclePolicy(current memoryloop.ActivationPolicy) memoryloop.ActivationPolicy {
148→	for i, p := range policyOrder {
149→		if p == current {
150→			return policyOrder[(i+1)%len(policyOrder)]
151→		}
152→	}
153→	return memoryloop.ActivationPolicyReview
154→}
